pub fn emit_rust_block_stmts(
    mut remaining: Rc<Vec<Rc<Node>>>,
    mut text: Rc<Vec<String>>,
    mut scope: Rc<InferScope>,
    mut registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    mut depth: i64,
    mut shared_types: Rc<std::collections::BTreeSet<String>>,
    mut emit_info: Rc<EmitGraphInfo>,
) -> Rc<BlockEmitState> {
    loop {
        match remaining.clone().first().cloned() {
            None => {
                break Rc::new(BlockEmitState {
                    text: text,
                    scope: scope.clone(),
                });
            }
            Some(stmt) => {
                let line = emit_typed_expr(
                    stmt.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    shared_types.clone(),
                    emit_info.clone(),
                    1024,
                );
                let next_scope = scope_after_expr(stmt.clone(), scope.clone());
                {
                    let __tco_0 = Rc::new(
                        remaining
                            .iter()
                            .cloned()
                            .skip(1 as usize)
                            .collect::<Vec<_>>(),
                    );
                    let __tco_1 = v1_rt::rc_list_push(text, line);
                    let __tco_2 = next_scope;
                    remaining = __tco_0;
                    text = __tco_1;
                    scope = __tco_2;
                    continue;
                }
            }
        }
    }
}

pub fn emit_rust_init_block_stmts(
    mut remaining: Rc<Vec<Rc<Node>>>,
    mut text: Rc<Vec<String>>,
    mut scope: Rc<InferScope>,
    mut registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    mut depth: i64,
    mut shared_types: Rc<std::collections::BTreeSet<String>>,
    mut emit_info: Rc<EmitGraphInfo>,
) -> Rc<BlockEmitState> {
    loop {
        match remaining.clone().first().cloned() {
            None => {
                break Rc::new(BlockEmitState {
                    text: text,
                    scope: scope.clone(),
                });
            }
            Some(stmt) => {
                let rest = Rc::new(
                    remaining
                        .clone()
                        .iter()
                        .cloned()
                        .skip(1 as usize)
                        .collect::<Vec<_>>(),
                );
                match rest.clone().first().cloned() {
                    None => {
                        break Rc::new(BlockEmitState {
                            text: text,
                            scope: scope.clone(),
                        });
                    }
                    Some(_) => {
                        let raw_line = emit_typed_expr(
                            stmt.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            shared_types.clone(),
                            emit_info.clone(),
                            1024,
                        );
                        let is_let = match (*stmt.expr_data.clone()).clone() {
                            ExprData::ExprLet => true,
                            _ => false,
                        };
                        let line = if is_let {
                            raw_line
                        } else {
                            v1_rt::concat(raw_line, ";".to_string())
                        };
                        let next_scope = scope_after_expr(stmt.clone(), scope.clone());
                        {
                            let __tco_0 = rest.clone();
                            let __tco_1 = v1_rt::rc_list_push(text, line);
                            let __tco_2 = next_scope;
                            remaining = __tco_0;
                            text = __tco_1;
                            scope = __tco_2;
                            continue;
                        }
                    }
                }
            }
        }
    }
}

pub fn rust_qualify_type_leaf_name(
    name: String,
    variant_to_enum: Rc<HashMap<String, String>>,
) -> String {
    match v1_rt::map_get(&variant_to_enum, name.clone()) {
        Some(parent) => {
            if (parent.clone() != "".to_string()) {
                v1_rt::concat(
                    v1_rt::concat(parent.clone(), "::".to_string()),
                    name.clone(),
                )
            } else {
                name.clone()
            }
        }
        None => name.clone(),
    }
}

pub fn rust_render_type_leaf_name(
    name: String,
    variant_to_enum: Rc<HashMap<String, String>>,
) -> String {
    if is_value_variant_type_arg(Rc::new(vec![]), variant_to_enum.clone(), name.clone()) {
        "()".to_string()
    } else {
        match rust_opaque_kernel_alias_carrier(name.clone()) {
            Some(carrier) => carrier.clone(),
            None => rust_qualify_type_leaf_name(name.clone(), variant_to_enum.clone()),
        }
    }
}

pub fn rust_phantom_zst_marker_def(vname: String) -> String {
    v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]\n".to_string(), rust_visibility_prefix()), rust_items().struct_keyword.clone()), " ".to_string()), vname), ";".to_string())
}

pub fn emit_phantom_zst_markers_for_enum(children: Rc<Vec<Rc<Node>>>, env: Rc<TypeEnv>) -> String {
    {
        let markers = Rc::new({
            let mut __result = Vec::new();
            for child in Rc::new({
                let mut __result = Vec::new();
                for child in Rc::new({
                    let mut __result = Vec::new();
                    for child in children.iter().cloned() {
                        if ((child.children.clone().len() as i64) == 0) {
                            __result.push(child);
                        }
                    }
                    __result
                })
                .iter()
                .cloned()
                {
                    if is_phantom_unit_variant_type_arg(
                        env.clone(),
                        authored_name(env.clone(), child.clone()),
                    ) {
                        __result.push(child);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push({
                    let vname = authored_name(env.clone(), child.clone());
                    rust_phantom_zst_marker_def(vname.clone())
                });
            }
            __result
        })
        .join(&"\n".to_string());
        markers
    }
}

pub fn collect_phantom_zst_marker_names(
    items: Rc<Vec<Rc<Node>>>,
    env: Rc<TypeEnv>,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for item in items.iter().cloned() {
            if (is_type_def_item(item.clone()) && {
                let mut __all = true;
                for c in item.children.clone().iter().cloned() {
                    if !((c.children.clone().len() as i64) == 0) {
                        __all = false;
                        break;
                    }
                }
                __all
            }) {
                __result.push(item);
            }
        }
        __result
    })
    .iter()
    .cloned()
    .fold(Rc::new(vec![]), |acc: Rc<Vec<String>>, item: Rc<Node>| {
        item.children.clone().iter().cloned().fold(
            acc,
            |inner: Rc<Vec<String>>, child: Rc<Node>| {
                if ((child.children.clone().len() as i64) == 0) {
                    {
                        let vname = authored_name(env.clone(), child.clone());
                        if (is_phantom_unit_variant_type_arg(env.clone(), vname.clone())
                            && !{
                                let mut __found = false;
                                for n in inner.clone().iter().cloned() {
                                    if (n.clone() == vname.clone()) {
                                        __found = true;
                                        break;
                                    }
                                }
                                __found
                            })
                        {
                            v1_rt::concat(inner.clone(), Rc::new(vec![vname.clone()]))
                        } else {
                            inner.clone()
                        }
                    }
                } else {
                    inner.clone()
                }
            },
        )
    })
}

pub fn emit_module_phantom_zst_markers(items: Rc<Vec<Rc<Node>>>, env: Rc<TypeEnv>) -> String {
    Rc::new({
        let mut __result = Vec::new();
        for vname in collect_phantom_zst_marker_names(items, env).iter().cloned() {
            __result.push(rust_phantom_zst_marker_def(vname.clone()));
        }
        __result
    })
    .join(&"\n".to_string())
}

pub fn has_complex_variants(item: Rc<Node>) -> bool {
    if ((item.children.clone().len() as i64) == 0) {
        false
    } else {
        {
            let mut __found = false;
            for c in item.children.clone().iter().cloned() {
                if (c.connective.clone() != Connective::NoConnective) {
                    __found = true;
                    break;
                }
            }
            __found
        }
    }
}

pub fn is_simple_disj(item: Rc<Node>) -> bool {
    {
        let complex = Rc::new({
            let mut __result = Vec::new();
            for v in item.children.clone().iter().cloned() {
                if ((v.children.clone().len() as i64) > 0) {
                    __result.push(v);
                }
            }
            __result
        });
        ((complex.len() as i64) == 0)
    }
}

