pub fn is_type_constant(
    summary: Rc<TypeSummary>,
    recursive_type_set: Rc<std::collections::BTreeSet<String>>,
) -> bool {
    {
        let is_recursive = v1_rt::set_contains(&recursive_type_set, summary.name.clone());
        let has_generics = ((summary.generic_param_names.clone().len() as i64) > 0);
        match (*summary.repr.clone()).clone() {
            TypeRepr::EnumRepr {
                unit_only: unit_only,
                ..
            } => {
                (((unit_only.clone() && !is_recursive) && !has_generics)
                    && !summary.has_fn_fields.clone())
            }
            TypeRepr::StructRepr => {
                if ((is_recursive || has_generics) || summary.has_fn_fields.clone()) {
                    false
                } else {
                    {
                        let field_count =
                            (Rc::new(v1_rt::map_keys(&summary.field_summaries.clone())).len()
                                as i64);
                        let ft_count = (Rc::new(v1_rt::map_keys(&summary.field_type_map.clone()))
                            .len() as i64);
                        if (ft_count < field_count) {
                            false
                        } else {
                            {
                                let mut __all = true;
                                for tn in
                                    Rc::new(v1_rt::map_values(&summary.field_type_map.clone()))
                                        .iter()
                                        .cloned()
                                {
                                    if !(is_dag_value_type_name(tn.clone())) {
                                        __all = false;
                                        break;
                                    }
                                }
                                __all
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn maybe_mark_shared_type(
    acc: Rc<std::collections::BTreeSet<String>>,
    summary: Rc<TypeSummary>,
    recursive_type_set: Rc<std::collections::BTreeSet<String>>,
    target_needs_sharing: bool,
) -> Rc<std::collections::BTreeSet<String>> {
    {
        let needs_sharing = (target_needs_sharing
            && match (*summary.repr.clone()).clone() {
                TypeRepr::StructRepr => true,
                TypeRepr::EnumRepr {
                    unit_only: unit_only,
                    ..
                } => (unit_only.clone() == false),
            });
        if (needs_sharing && !is_type_constant(summary.clone(), recursive_type_set)) {
            v1_rt::rc_set_insert(acc, summary.name.clone())
        } else {
            acc
        }
    }
}

pub fn build_shared_types(
    type_summaries: Rc<HashMap<String, Rc<TypeSummary>>>,
    recursive_type_set: Rc<std::collections::BTreeSet<String>>,
    target: RenderTarget,
) -> Rc<std::collections::BTreeSet<String>> {
    {
        let sharing = sharing_for_target(target);
        let user_shared = Rc::new(v1_rt::map_values(&type_summaries))
            .iter()
            .cloned()
            .fold(
                v1_rt::rc_empty_set::<String>(),
                |acc: Rc<std::collections::BTreeSet<String>>, summary: Rc<TypeSummary>| {
                    maybe_mark_shared_type(
                        acc,
                        summary.clone(),
                        recursive_type_set.clone(),
                        sharing.needs_sharing.clone(),
                    )
                },
            );
        let collection_keys = Rc::new({
            let mut __result = Vec::new();
            for k in Rc::new(v1_rt::map_keys(&rust_container_templates()))
                .iter()
                .cloned()
            {
                if ((sharing.needs_sharing.clone() && (k.clone() != "optional".to_string()))
                    && (k.clone() != "boolean_algebra".to_string()))
                {
                    __result.push(k);
                }
            }
            __result
        });
        collection_keys.iter().cloned().fold(
            user_shared.clone(),
            |acc: Rc<std::collections::BTreeSet<String>>, key: String| {
                let pascal = to_pascal(key.clone());
                v1_rt::rc_set_insert(acc, pascal.clone())
            },
        )
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OwnershipProofEntry {
    pub name: String,
    pub proof: Rc<OwnershipProof>,
    pub param_names: Rc<std::collections::BTreeSet<String>>,
    pub move_sites: Rc<HashMap<String, bool>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct OwnershipBuildResult {
    pub ownership_index: Rc<HashMap<String, Rc<std::collections::BTreeSet<String>>>>,
    pub read_only_params_index: Rc<HashMap<String, Rc<std::collections::BTreeSet<String>>>>,
    pub move_sites_index: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
}

pub fn build_ownership_results(modules: Rc<Vec<Rc<TypedModule>>>) -> Rc<OwnershipBuildResult> {
    {
        let callable_set = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_set::<_>(),
            |acc: _, m: Rc<TypedModule>| {
                Rc::new({
                    let mut __result = Vec::new();
                    for item in m.items.clone().iter().cloned() {
                        if (item.body.clone() != None) {
                            __result.push(item);
                        }
                    }
                    __result
                })
                .iter()
                .cloned()
                .fold(acc, |inner: _, item: Rc<Node>| {
                    v1_rt::rc_set_union(
                        inner,
                        collect_callable_refs(
                            item.body.clone().clone().unwrap(),
                            (*m.type_env).clone().source_indices.clone(),
                        ),
                    )
                })
            },
        );
        let proofs = Rc::new({
            let mut __result = Vec::new();
            for m in modules.clone().iter().cloned() {
                __result.extend(
                    (*Rc::new({
                        let mut __result = Vec::new();
                        for item in Rc::new({
                            let mut __result = Vec::new();
                            for item in m.items.clone().iter().cloned() {
                                if (item.body.clone() != None) {
                                    __result.push(item);
                                }
                            }
                            __result
                        })
                        .iter()
                        .cloned()
                        {
                            __result.push({
                                let pnames = item.params.clone().iter().cloned().fold(
                                    v1_rt::rc_empty_set::<_>(),
                                    |acc: _, p: Rc<Node>| {
                                        v1_rt::rc_set_insert(
                                            acc,
                                            param_node_name_at(
                                                p.clone(),
                                                (*m.type_env).clone().source_indices.clone(),
                                            ),
                                        )
                                    },
                                );
                                let si = (*m.type_env).clone().source_indices.clone();
                                let qualified = v1_rt::concat(
                                    v1_rt::concat(
                                        authored_name_at(si.clone(), m.module.clone()),
                                        ".".to_string(),
                                    ),
                                    authored_name_at(si.clone(), item.clone()),
                                );
                                Rc::new(OwnershipProofEntry {
                                    name: qualified.clone(),
                                    proof: analyze_ownership(
                                        authored_name_at(si.clone(), item.clone()),
                                        item.params.clone(),
                                        item.body.clone().clone().unwrap(),
                                        si.clone(),
                                    ),
                                    param_names: pnames.clone(),
                                    move_sites: build_move_site_licenses(
                                        item.body.clone().clone().unwrap(),
                                        si.clone(),
                                    ),
                                })
                            });
                        }
                        __result
                    }))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        proofs.iter().cloned().fold(
            Rc::new(OwnershipBuildResult {
                ownership_index: v1_rt::rc_empty_map::<
                    String,
                    Rc<std::collections::BTreeSet<String>>,
                >(),
                read_only_params_index: v1_rt::rc_empty_map::<
                    String,
                    Rc<std::collections::BTreeSet<String>>,
                >(),
                move_sites_index: v1_rt::rc_empty_map::<String, Rc<HashMap<String, bool>>>(),
            }),
            |acc: Rc<OwnershipBuildResult>, entry: Rc<OwnershipProofEntry>| {
                let acc = Rc::try_unwrap(acc).unwrap_or_else(|rc| (*rc).clone());
                {
                    let read_only = if v1_rt::set_contains(
                        &callable_set,
                        entry.proof.clone().func_name.clone(),
                    ) {
                        v1_rt::rc_empty_set::<String>()
                    } else {
                        build_read_only_params(entry.proof.clone(), entry.param_names.clone())
                    };
                    let movable = build_movable_set(entry.proof.clone(), entry.param_names.clone());
                    Rc::new(OwnershipBuildResult {
                        ownership_index: v1_rt::rc_map_insert(
                            acc.ownership_index,
                            entry.name.clone(),
                            movable.clone(),
                        ),
                        read_only_params_index: v1_rt::rc_map_insert(
                            acc.read_only_params_index,
                            entry.name.clone(),
                            read_only.clone(),
                        ),
                        move_sites_index: v1_rt::rc_map_insert(
                            acc.move_sites_index,
                            entry.name.clone(),
                            entry.move_sites.clone(),
                        ),
                    })
                }
            },
        )
    }
}

pub fn emit_rust(typed: Rc<ResolvedGraph>) -> Rc<EmitResult> {
    {
        let base_info = build_emit_graph_info(typed.modules.clone());
        let ownership = build_ownership_results(typed.modules.clone());
        let shared = build_shared_types(
            base_info.type_summaries.clone(),
            base_info.recursive_type_set.clone(),
            RenderTarget::Rust,
        );
        let emit_info = Rc::new(EmitGraphInfo {
            type_summaries: base_info.type_summaries.clone(),
            recursive_type_set: base_info.recursive_type_set.clone(),
            fielded_variants: base_info.fielded_variants.clone(),
            positional_payload_variants: base_info.positional_payload_variants.clone(),
            shared_types: shared,
            ownership_index: ownership.ownership_index.clone(),
            movable: v1_rt::rc_empty_set::<String>(),
            variant_to_enum: base_info.variant_to_enum.clone(),
            owned_bindings: v1_rt::rc_empty_set::<String>(),
            move_sites_index: ownership.move_sites_index.clone(),
            move_sites: v1_rt::rc_empty_map::<String, bool>(),
            read_only_params_index: ownership.read_only_params_index.clone(),
            read_only_params: v1_rt::rc_empty_set::<String>(),
            corpus_repr: base_info.corpus_repr.clone(),
        });
        let shared_types = emit_info.shared_types.clone();
        let registry = typed.item_registry.clone();
        let data_items = build_data_item_index(typed.modules.clone());
        let workflow_funcs = collect_workflow_funcs(
            typed.modules.clone(),
            registry.clone(),
            emit_info.read_only_params_index.clone(),
        );
        let workflow_default_diags = validate_workflow_param_defaults(workflow_funcs.clone());
        if ((workflow_default_diags.clone().len() as i64) > 0) {
            return Rc::new(EmitResult {
                files: Rc::new(vec![]),
                diagnostics: workflow_default_diags.clone(),
            });
        }
        let svc_module_map = typed.modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, String>(),
            |acc: Rc<HashMap<String, String>>, tm: Rc<TypedModule>| {
                let svc_items = Rc::new({
                    let mut __result = Vec::new();
                    for item in tm.items.clone().iter().cloned() {
                        if is_service_item(item.clone()) {
                            __result.push(item);
                        }
                    }
                    __result
                });
                let mod_filename = module_to_filename(authored_name_at(
                    (*tm.type_env).clone().source_indices.clone(),
                    tm.module.clone(),
                ));
                svc_items.clone().iter().cloned().fold(
                    acc,
                    |a: Rc<HashMap<String, String>>, svc: Rc<Node>| {
                        v1_rt::rc_map_insert(
                            a,
                            authored_name_at(
                                (*tm.type_env).clone().source_indices.clone(),
                                svc.clone(),
                            ),
                            mod_filename.clone(),
                        )
                    },
                )
            },
        );
        let test_projections = extract_test_projections(typed.clone());
        let export_sets = build_module_export_sets(typed.modules.clone());
        let module_index = build_module_index(typed.modules.clone());
        let module_files = Rc::new({
            let mut __result = Vec::new();
            for tm in typed.modules.clone().iter().cloned() {
                __result.push(emit_module_full(
                    tm.clone(),
                    registry.clone(),
                    emit_info.clone(),
                    shared_types.clone(),
                    svc_module_map.clone(),
                    data_items.clone(),
                    export_sets.clone(),
                    typed.modules.clone(),
                    module_index.clone(),
                ));
            }
            __result
        });
        let test_files = Rc::new({
            let mut __result = Vec::new();
            for f in Rc::new({
                let mut __result = Vec::new();
                for tm in typed.modules.clone().iter().cloned() {
                    __result.push(emit_test_file(
                        authored_name_at(
                            (*tm.type_env).clone().source_indices.clone(),
                            tm.module.clone(),
                        ),
                        Rc::new({
                            let mut __result = Vec::new();
                            for p in test_projections.clone().iter().cloned() {
                                if (p.module_name.clone()
                                    == authored_name_at(
                                        (*tm.type_env).clone().source_indices.clone(),
                                        tm.module.clone(),
                                    ))
                                {
                                    __result.push(p);
                                }
                            }
                            __result
                        }),
                        emit_info.corpus_repr.clone(),
                    ));
                }
                __result
            })
            .iter()
            .cloned()
            {
                if (f.path.clone() != "".to_string()) {
                    __result.push(f);
                }
            }
            __result
        });
        let has_services = has_service_items(typed.clone());
        let has_pipeline = {
            let mut __found = false;
            for m in typed.modules.clone().iter().cloned() {
                if (authored_name_at(
                    (*m.type_env).clone().source_indices.clone(),
                    m.module.clone(),
                ) == "v1.compiler.compile".to_string())
                {
                    __found = true;
                    break;
                }
            }
            __found
        };
        let crate_name = if has_pipeline.clone() {
            "v1_compiler".to_string()
        } else {
            "v1_compiled".to_string()
        };
        let cargo = emit_cargo_toml(crate_name.clone(), has_services.clone());
        let main_file = emit_main_rs(
            workflow_funcs.clone(),
            typed.modules.clone(),
            has_services.clone(),
            crate_name.clone(),
            svc_module_map.clone(),
        );
        let rt_file = emit_v2_rt_module();
        let compiler_tests_file = if has_pipeline.clone() {
            Rc::new(vec![emit_compiler_tests_module()])
        } else {
            Rc::new(vec![])
        };
        let dry_run_file = if has_services.clone() {
            Rc::new(vec![emit_dry_run_module()])
        } else {
            Rc::new(vec![])
        };
        let all_mod_files = v1_rt::concat(
            v1_rt::concat(module_files, Rc::new(vec![rt_file])),
            dry_run_file,
        );
        let lib_file = emit_lib_rs_from_files(all_mod_files.clone(), has_pipeline.clone());
        let files = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    Rc::new(vec![cargo, lib_file, main_file]),
                    all_mod_files.clone(),
                ),
                compiler_tests_file,
            ),
            test_files,
        );
        Rc::new(EmitResult {
            files: files,
            diagnostics: Rc::new(vec![]),
        })
    }
}

pub fn emit_v2_rt_module() -> Rc<TextFile> {
    Rc::new(TextFile {
        path: v1_rt::concat(
            v1_rt::concat(rust_source_root(), "v1_rt".to_string()),
            rust_source_ext(),
        ),
        content: rust_runtime_source(),
    })
}

pub fn emit_compiler_tests_module() -> Rc<TextFile> {
    Rc::new(TextFile {
        path: v1_rt::concat(
            v1_rt::concat(rust_source_root(), "compiler_tests".to_string()),
            rust_source_ext(),
        ),
        content: compiler_tests_source(),
    })
}

pub fn emit_lib_rs_from_files(
    all_module_files: Rc<Vec<Rc<TextFile>>>,
    has_compiler_tests: bool,
) -> Rc<TextFile> {
    {
        let src_prefix_len = v1_rt::string_length(&rust_source_root());
        let ext_len = v1_rt::string_length(&rust_source_ext());
        let mod_decls = Rc::new({
            let mut __result = Vec::new();
            for f in all_module_files.iter().cloned() {
                __result.push({
                    let path_len = v1_rt::string_length(&f.path.clone());
                    let mod_name = v1_rt::substring(
                        &f.path.clone(),
                        src_prefix_len.clone(),
                        (path_len.clone() - ext_len.clone()),
                    );
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    rust_visibility_prefix(),
                                    rust_items().module_keyword.clone(),
                                ),
                                " ".to_string(),
                            ),
                            mod_name.clone(),
                        ),
                        ";".to_string(),
                    )
                });
            }
            __result
        });
        let hand_maintained_mods = if has_compiler_tests.clone() {
            "\npub mod v1_interpreter;\npub mod cli_run;\npub mod coproduct_reflection;\npub mod resolved_graph_cache;\npub mod recorded_fixture;\npub mod module_path_index;".to_string()
        } else {
            "".to_string()
        };
        let test_mod = if has_compiler_tests.clone() {
            "\n\n#[cfg(test)]\nmod compiler_tests;".to_string()
        } else {
            "".to_string()
        };
        let shared_types = emit_non_empty_wrappers();
        let content = v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("// Generated by v1 compiler -- do not edit.\n\n".to_string(), "#![allow(unused_imports, unused_variables, unused_mut, unused_parens, dead_code, unreachable_patterns, non_shorthand_field_patterns, suspicious_double_ref_op, clippy::all)]\n".to_string()), "#![recursion_limit = \"256\"]\n\n".to_string()), mod_decls.join(&"\n".to_string())), hand_maintained_mods), "\n\n".to_string()), shared_types), test_mod);
        Rc::new(TextFile {
            path: v1_rt::concat(
                v1_rt::concat(rust_source_root(), "lib".to_string()),
                rust_source_ext(),
            ),
            content: v1_rt::concat(content, "\n".to_string()),
        })
    }
}

pub fn emit_module(
    typed_module: Rc<TypedModule>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
) -> Rc<TextFile> {
    {
        let base_info = build_emit_graph_info(Rc::new(vec![typed_module.clone()]));
        let shared = build_shared_types(
            base_info.type_summaries.clone(),
            base_info.recursive_type_set.clone(),
            RenderTarget::Rust,
        );
        let emit_info = Rc::new(EmitGraphInfo {
            type_summaries: base_info.type_summaries.clone(),
            recursive_type_set: base_info.recursive_type_set.clone(),
            fielded_variants: base_info.fielded_variants.clone(),
            positional_payload_variants: base_info.positional_payload_variants.clone(),
            shared_types: shared,
            ownership_index: base_info.ownership_index.clone(),
            movable: base_info.movable.clone(),
            variant_to_enum: base_info.variant_to_enum.clone(),
            owned_bindings: v1_rt::rc_empty_set::<String>(),
            move_sites_index: base_info.move_sites_index.clone(),
            move_sites: base_info.move_sites.clone(),
            read_only_params_index: base_info.read_only_params_index.clone(),
            read_only_params: v1_rt::rc_empty_set::<String>(),
            corpus_repr: base_info.corpus_repr.clone(),
        });
        let shared_types = emit_info.shared_types.clone();
        let export_sets = build_module_export_sets(Rc::new(vec![typed_module.clone()]));
        let module_index = build_module_index(Rc::new(vec![typed_module.clone()]));
        emit_module_full(
            typed_module.clone(),
            registry,
            emit_info.clone(),
            shared_types,
            v1_rt::rc_empty_map::<String, String>(),
            build_data_item_index(Rc::new(vec![typed_module.clone()])),
            export_sets,
            Rc::new(vec![typed_module.clone()]),
            module_index,
        )
    }
}

pub fn build_module_export_sets(
    modules: Rc<Vec<Rc<TypedModule>>>,
) -> Rc<HashMap<String, Rc<HashMap<String, bool>>>> {
    modules.iter().cloned().fold(
        v1_rt::rc_empty_map::<String, Rc<HashMap<String, bool>>>(),
        |acc: Rc<HashMap<String, Rc<HashMap<String, bool>>>>, tm: Rc<TypedModule>| {
            let m_name = authored_name_at(
                (*tm.type_env).clone().source_indices.clone(),
                tm.module.clone(),
            );
            let exported = get_exported_names(
                tm.module.clone(),
                (*tm.type_env).clone().source_indices.clone(),
            );
            let exported_set = exported.clone().iter().cloned().fold(
                v1_rt::rc_empty_map::<String, bool>(),
                |inner: Rc<HashMap<String, bool>>, n: String| {
                    v1_rt::rc_map_insert(inner, n.clone(), true)
                },
            );
            v1_rt::rc_map_insert(acc, m_name.clone(), exported_set.clone())
        },
    )
}

pub fn emit_module_full(
    typed_module: Rc<TypedModule>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    emit_info: Rc<EmitGraphInfo>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    svc_module_map: Rc<HashMap<String, String>>,
    data_items: Rc<HashMap<String, Rc<Node>>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    module_index: Rc<ModuleIndex>,
) -> Rc<TextFile> {
    {
        let m = (*typed_module.module).clone();
        let scope = module_emit_scope(typed_module.clone());
        let scoped_data_items = augment_scoped_data_item_index_with_imports(
            build_scoped_data_item_index(typed_module.clone(), data_items.clone()),
            contracts_imports_for_module(
                authored_name(scope.type_env.clone(), Rc::new(m.clone())),
                typed_modules.clone(),
                (*scope.type_env).clone().source_indices.clone(),
                module_index.clone(),
            ),
            (*scope.type_env).clone().source_indices.clone(),
            data_items.clone(),
        );
        let prelude_imported_names = Rc::new({
            let mut __result = Vec::new();
            for imp in module_imports(Rc::new(m.clone())).iter().cloned() {
                __result.extend(
                    (*import_specific_names_at(
                        imp.clone(),
                        (*scope.type_env).clone().source_indices.clone(),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let prelude = emit_prelude(prelude_imported_names);
        let local_type_names = Rc::new({
            let mut __result = Vec::new();
            for item in Rc::new({
                let mut __result = Vec::new();
                for item in typed_module.items.clone().iter().cloned() {
                    if ((is_type_def_item(item.clone())
                        || is_type_alias_item(
                            item.clone(),
                            (*scope.type_env).clone().source_indices.clone(),
                        ))
                        || is_type_decl_item(
                            item.clone(),
                            (*scope.type_env).clone().source_indices.clone(),
                        ))
                    {
                        __result.push(item);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(authored_name(scope.type_env.clone(), item.clone()));
            }
            __result
        });
        let imports_str = emit_imports(
            module_imports(Rc::new(m.clone())),
            emit_info.clone(),
            registry.clone(),
            local_type_names,
            export_sets.clone(),
            typed_modules.clone(),
            (*scope.type_env).clone().source_indices.clone(),
            module_index.clone(),
        );
        let imports_section = if (imports_str.clone() == "".to_string()) {
            "".to_string()
        } else {
            v1_rt::concat("\n".to_string(), imports_str.clone())
        };
        let this_mod_filename =
            module_to_filename(authored_name(scope.type_env.clone(), Rc::new(m.clone())));
        let all_svc_names = Rc::new({
            let mut __result = Vec::new();
            for item in typed_module.items.clone().iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(
                        &registry,
                        authored_name(scope.type_env.clone(), item.clone()),
                    ) {
                        Some(info) => info.service_names.clone(),
                        None => Rc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let extern_svc_imports = Rc::new({
            let mut __result = Vec::new();
            for sn in unique_strings(all_svc_names).iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(&svc_module_map, sn.clone()) {
                        Some(mod_file) => {
                            if (mod_file.clone() == this_mod_filename.clone()) {
                                Rc::new(vec![])
                            } else {
                                Rc::new(vec![v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    rust_visibility_prefix(),
                                                    "use crate::".to_string(),
                                                ),
                                                mod_file.clone(),
                                            ),
                                            "::".to_string(),
                                        ),
                                        sanitize_service_name(sn.clone()),
                                    ),
                                    ";".to_string(),
                                )])
                            }
                        }
                        None => Rc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let svc_imports_str = if ((extern_svc_imports.clone().len() as i64) == 0) {
            "".to_string()
        } else {
            v1_rt::concat(
                "\n".to_string(),
                extern_svc_imports.clone().join(&"\n".to_string()),
            )
        };
        let local_enum_uses = Rc::new({
            let mut __result = Vec::new();
            for item in Rc::new({
                let mut __result = Vec::new();
                for item in typed_module.items.clone().iter().cloned() {
                    if ((is_type_def_item(item.clone()) && is_coproduct_type(item.clone()))
                        && !is_host_freemonoid_vec_alias(
                            authored_name(scope.type_env.clone(), item.clone()),
                            emit_info.corpus_repr.clone(),
                        ))
                    {
                        __result.push(item);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(v1_rt::concat(
                    v1_rt::concat(
                        "use self::".to_string(),
                        authored_name(scope.type_env.clone(), item.clone()),
                    ),
                    "::*;".to_string(),
                ));
            }
            __result
        });
        let local_coproduct_names = Rc::new({
            let mut __result = Vec::new();
            for item in Rc::new({
                let mut __result = Vec::new();
                for item in typed_module.items.clone().iter().cloned() {
                    if (is_type_def_item(item.clone()) && is_coproduct_type(item.clone())) {
                        __result.push(item);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(authored_name(scope.type_env.clone(), item.clone()));
            }
            __result
        });
        let module_import_items = module_imports(Rc::new(m.clone()));
        let this_module_name = authored_name(scope.type_env.clone(), Rc::new(m.clone()));
        let wire_context_items = v1_rt::concat(
            typed_module.items.clone(),
            contracts_items_for_module(
                this_module_name.clone(),
                typed_modules.clone(),
                (*scope.type_env).clone().source_indices.clone(),
                module_index.clone(),
            ),
        );
        let wire_context_imports = v1_rt::concat(
            module_import_items,
            contracts_imports_for_module(
                this_module_name.clone(),
                typed_modules.clone(),
                (*scope.type_env).clone().source_indices.clone(),
                module_index.clone(),
            ),
        );
        let coproduct_wire_contract_validations = emit_coproduct_wire_contract_validations(
            wire_context_items.clone(),
            wire_context_imports.clone(),
            local_coproduct_names,
            (*scope.type_env).clone().source_indices.clone(),
        );
        let coproduct_wire_contract_validation_section =
            if (coproduct_wire_contract_validations.clone() == "".to_string()) {
                "".to_string()
            } else {
                v1_rt::concat(
                    coproduct_wire_contract_validations.clone(),
                    "\n\n".to_string(),
                )
            };
        let local_uses_str = if ((local_enum_uses.clone().len() as i64) == 0) {
            "".to_string()
        } else {
            v1_rt::concat(
                "\n".to_string(),
                local_enum_uses.clone().join(&"\n".to_string()),
            )
        };
        let wire_contract_item = Rc::new({
            let mut __result = Vec::new();
            for i in wire_context_items.clone().iter().cloned() {
                if (is_data_def_item(i.clone())
                    && (authored_name_at(
                        (*scope.type_env).clone().source_indices.clone(),
                        i.clone(),
                    ) == "wire_contract".to_string()))
                {
                    __result.push(i);
                }
            }
            __result
        })
        .first()
        .cloned();
        let items_str = Rc::new({
            let mut __result = Vec::new();
            for item in typed_module.items.clone().iter().cloned() {
                __result.push(emit_typed_item(
                    item.clone(),
                    authored_name(scope.type_env.clone(), Rc::new(m.clone())),
                    registry.clone(),
                    scope.clone(),
                    shared_types.clone(),
                    emit_info.clone(),
                    wire_contract_item.clone(),
                    scoped_data_items.clone(),
                    wire_context_items.clone(),
                    wire_context_imports.clone(),
                    export_sets.clone(),
                    typed_modules.clone(),
                    module_index.clone(),
                ));
            }
            __result
        })
        .join(&"\n\n".to_string());
        let phantom_zst_markers =
            emit_module_phantom_zst_markers(typed_module.items.clone(), scope.type_env.clone());
        let phantom_section = if (phantom_zst_markers.clone() == "".to_string()) {
            "".to_string()
        } else {
            v1_rt::concat("\n\n".to_string(), phantom_zst_markers.clone())
        };
        let raw_filename = module_to_filename(authored_name(scope.type_env.clone(), Rc::new(m.clone())));
        let filename = if (raw_filename.clone() == "main".to_string()) {
            "main_mod".to_string()
        } else {
            raw_filename.clone()
        };
        let module_attrs = if (authored_name(scope.type_env.clone(), Rc::new(m.clone()))
            == "std.error_primitives".to_string())
        {
            "#![allow(non_camel_case_types)]\n\n".to_string()
        } else {
            "".to_string()
        };
        let content = v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("// Generated by v1 compiler -- do not edit.\n".to_string(), "// Source module: ".to_string()), authored_name(scope.type_env.clone(), Rc::new(m.clone()))), "\n\n".to_string()), module_attrs), prelude), imports_section), svc_imports_str), local_uses_str), "\n\n".to_string()), coproduct_wire_contract_validation_section), items_str), phantom_section), "\n".to_string());
        Rc::new(TextFile {
            path: v1_rt::concat(
                v1_rt::concat(rust_source_root(), filename),
                rust_source_ext(),
            ),
            content: content,
        })
    }
}

pub fn emit_import_name(n: String, registry: Rc<HashMap<String, Rc<ItemInfo>>>) -> String {
    {
        let is_data = match v1_rt::map_get(&registry, n.clone()) {
            Some(info) => (info.kind.clone() == ItemKind::DataItem),
            None => false,
        };
        if is_data {
            to_snake(n.clone())
        } else {
            n.clone()
        }
    }
}

pub fn is_import_graph_type_name(
    name: String,
    import_module: String,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    type_summaries: Rc<HashMap<String, Rc<TypeSummary>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_index: Rc<ModuleIndex>,
) -> bool {
    if has_physical_type_def_in_module_filename(
        name.clone(),
        module_to_filename(import_module.clone()),
        typed_modules.clone(),
        source_indices.clone(),
        module_index.clone(),
    ) {
        true
    } else {
        if match reexport_source_module_name(
            name.clone(),
            import_module.clone(),
            typed_modules.clone(),
            export_sets.clone(),
            source_indices.clone(),
            module_index.clone(),
        ) {
            Some(src) => type_name_is_rust_importable_in_module(
                name.clone(),
                src.clone(),
                typed_modules.clone(),
                registry.clone(),
                export_sets.clone(),
                source_indices.clone(),
                module_index.clone(),
            ),
            None => false,
        } {
            true
        } else {
            if is_enum_in_summaries(type_summaries.clone(), name.clone()) {
                false
            } else {
                if is_known_variant(type_summaries.clone(), name.clone()) {
                    false
                } else {
                    match v1_rt::map_get(&export_sets, import_module.clone()) {
                        Some(exported) => {
                            if (v1_rt::map_get(&exported, name.clone()) == Some(true)) {
                                type_name_is_rust_importable_in_module(
                                    name.clone(),
                                    import_module.clone(),
                                    typed_modules.clone(),
                                    registry.clone(),
                                    export_sets.clone(),
                                    source_indices.clone(),
                                    module_index.clone(),
                                )
                            } else {
                                false
                            }
                        }
                        None => false,
                    }
                }
            }
        }
    }
}

pub fn item_defining_module_filename(
    name: String,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    fallback: String,
) -> String {
    match lookup_item(registry, name) {
        Some(info) => module_to_filename(info.module_name.clone()),
        None => fallback,
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ModuleIndex {
    pub by_name: Rc<HashMap<String, Rc<TypedModule>>>,
    pub by_filename: Rc<HashMap<String, Rc<Vec<Rc<TypedModule>>>>>,
}

pub fn build_module_index(modules: Rc<Vec<Rc<TypedModule>>>) -> Rc<ModuleIndex> {
    {
        let by_name = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<TypedModule>>(),
            |acc: Rc<HashMap<String, Rc<TypedModule>>>, tm: Rc<TypedModule>| {
                let nm = authored_name_at(
                    (*tm.type_env).clone().source_indices.clone(),
                    tm.module.clone(),
                );
                match v1_rt::map_get(&acc, nm.clone()) {
                    Some(_) => acc.clone(),
                    None => v1_rt::rc_map_insert(acc.clone(), nm.clone(), tm.clone()),
                }
            },
        );
        let by_filename = modules.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<Vec<Rc<TypedModule>>>>(),
            |acc: Rc<HashMap<String, Rc<Vec<Rc<TypedModule>>>>>, tm: Rc<TypedModule>| {
                let fname = module_to_filename(authored_name_at(
                    (*tm.type_env).clone().source_indices.clone(),
                    tm.module.clone(),
                ));
                match v1_rt::map_get(&acc, fname.clone()) {
                    Some(prior) => v1_rt::rc_map_insert(
                        acc.clone(),
                        fname.clone(),
                        v1_rt::rc_list_push(prior.clone(), tm.clone()),
                    ),
                    None => {
                        v1_rt::rc_map_insert(acc.clone(), fname.clone(), Rc::new(vec![tm.clone()]))
                    }
                }
            },
        );
        Rc::new(ModuleIndex {
            by_name: by_name,
            by_filename: by_filename,
        })
    }
}

