pub fn name_in_transitive_export_surface(
    name: String,
    module_name: String,
    visited: Rc<Vec<String>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_index: Rc<ModuleIndex>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if {
            let mut __found = false;
            for v in visited.clone().iter().cloned() {
                if (v.clone() == module_name.clone()) {
                    __found = true;
                    break;
                }
            }
            __found
        } {
            false
        } else {
            {
                let in_local = match v1_rt::map_get(&export_sets, module_name.clone()) {
                    Some(exported) => (v1_rt::map_get(&exported, name.clone()) == Some(true)),
                    None => false,
                };
                if in_local {
                    true
                } else {
                    match typed_module_by_name(
                        module_name.clone(),
                        typed_modules.clone(),
                        source_indices.clone(),
                        module_index.clone(),
                    ) {
                        None => false,
                        Some(tm) => {
                            let mut __found = false;
                            for imp in Rc::new({
                                let mut __result = Vec::new();
                                for imp in module_imports(tm.module.clone()).iter().cloned() {
                                    if import_is_all(imp.clone()) {
                                        __result.push(imp);
                                    }
                                }
                                __result
                            })
                            .iter()
                            .cloned()
                            {
                                if name_in_transitive_export_surface(
                                    name.clone(),
                                    authored_name_at(source_indices.clone(), imp.clone()),
                                    v1_rt::concat(
                                        visited.clone(),
                                        Rc::new(vec![module_name.clone()]),
                                    ),
                                    export_sets.clone(),
                                    typed_modules.clone(),
                                    source_indices.clone(),
                                    module_index.clone(),
                                ) {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        }
                    }
                }
            }
        }
    })
}

