pub fn reexport_source_module_name_with_visited(
    mut name: String,
    mut import_module: String,
    mut visited: Rc<Vec<String>>,
    mut typed_modules: Rc<Vec<Rc<TypedModule>>>,
    mut export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    mut module_index: Rc<ModuleIndex>,
) -> Option<String> {
    loop {
        if {
            let mut __found = false;
            for v in visited.clone().iter().cloned() {
                if (v.clone() == import_module.clone()) {
                    __found = true;
                    break;
                }
            }
            __found
        } {
            break None;
        } else {
            match typed_module_by_name(
                import_module.clone(),
                typed_modules.clone(),
                source_indices.clone(),
                module_index.clone(),
            ) {
                None => {
                    break None;
                }
                Some(tm) => {
                    if type_name_is_export_source_in_module(
                        name.clone(),
                        import_module.clone(),
                        typed_modules.clone(),
                        source_indices.clone(),
                        module_index.clone(),
                    ) {
                        break Some(import_module.clone());
                    } else {
                        match find_variant_parent_in_module(
                            name.clone(),
                            import_module.clone(),
                            typed_modules.clone(),
                            source_indices.clone(),
                            module_index.clone(),
                        ) {
                            Some(_parent) => {
                                break Some(import_module.clone());
                            }
                            None => {
                                match Rc::new({
                                    let mut __result = Vec::new();
                                    for imp in Rc::new({
                                        let mut __result = Vec::new();
                                        for imp in
                                            module_imports(tm.module.clone()).iter().cloned()
                                        {
                                            if ((import_is_all(imp.clone()) == false) && {
                                                let mut __found = false;
                                                for n in import_specific_names_at(
                                                    imp.clone(),
                                                    source_indices.clone(),
                                                )
                                                .iter()
                                                .cloned()
                                                {
                                                    if (n.clone() == name.clone()) {
                                                        __found = true;
                                                        break;
                                                    }
                                                }
                                                __found
                                            }) {
                                                __result.push(imp);
                                            }
                                        }
                                        __result
                                    })
                                    .iter()
                                    .cloned()
                                    {
                                        __result.push(authored_name_at(
                                            source_indices.clone(),
                                            imp.clone(),
                                        ));
                                    }
                                    __result
                                })
                                .first()
                                .cloned()
                                {
                                    Some(src) => {
                                        let __tco_0 = src.clone();
                                        let __tco_1 =
                                            v1_rt::concat(visited, Rc::new(vec![import_module]));
                                        import_module = __tco_0;
                                        visited = __tco_1;
                                        continue;
                                    }
                                    None => {
                                        match Rc::new({
                                            let mut __result = Vec::new();
                                            for imp in Rc::new({
                                                let mut __result = Vec::new();
                                                for imp in Rc::new({
                                                    let mut __result = Vec::new();
                                                    for imp in module_imports(tm.module.clone())
                                                        .iter()
                                                        .cloned()
                                                    {
                                                        if import_is_all(imp.clone()) {
                                                            __result.push(imp);
                                                        }
                                                    }
                                                    __result
                                                })
                                                .iter()
                                                .cloned()
                                                {
                                                    if {
                                                        let src_mod = authored_name_at(
                                                            source_indices.clone(),
                                                            imp.clone(),
                                                        );
                                                        name_in_transitive_export_surface(
                                                            name.clone(),
                                                            src_mod.clone(),
                                                            v1_rt::concat(
                                                                visited.clone(),
                                                                Rc::new(
                                                                    vec![import_module.clone()],
                                                                ),
                                                            ),
                                                            export_sets.clone(),
                                                            typed_modules.clone(),
                                                            source_indices.clone(),
                                                            module_index.clone(),
                                                        )
                                                    } {
                                                        __result.push(imp);
                                                    }
                                                }
                                                __result
                                            })
                                            .iter()
                                            .cloned()
                                            {
                                                __result.push(authored_name_at(
                                                    source_indices.clone(),
                                                    imp.clone(),
                                                ));
                                            }
                                            __result
                                        })
                                        .first()
                                        .cloned()
                                        {
                                            Some(src) => {
                                                let __tco_0 = src.clone();
                                                let __tco_1 = v1_rt::concat(
                                                    visited,
                                                    Rc::new(vec![import_module]),
                                                );
                                                import_module = __tco_0;
                                                visited = __tco_1;
                                                continue;
                                            }
                                            None => {
                                                break None;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn import_module_enum_scope(
    import_module: String,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    type_summaries: Rc<HashMap<String, Rc<TypeSummary>>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_index: Rc<ModuleIndex>,
) -> Rc<Vec<String>> {
    {
        let physical = enum_names_in_module(
            import_module.clone(),
            typed_modules.clone(),
            source_indices.clone(),
            type_summaries.clone(),
            module_index.clone(),
        );
        let reexport_parents = match v1_rt::map_get(&export_sets, import_module.clone()) {
            Some(exported) => Rc::new({
                let mut __result = Vec::new();
                for p in Rc::new({
                    let mut __result = Vec::new();
                    for n in Rc::new({
                        let mut __result = Vec::new();
                        for n in Rc::new({
                            let mut __sorted: Vec<_> = Rc::new(v1_rt::map_keys(&exported))
                                .iter()
                                .cloned()
                                .collect();
                            __sorted.sort_by(|a: &String, b: &String| {
                                let __ka = (|k: String| k.clone())(a.clone());
                                let __kb = (|k: String| k.clone())(b.clone());
                                __ka.partial_cmp(&__kb).unwrap_or(std::cmp::Ordering::Equal)
                            });
                            __sorted
                        })
                        .iter()
                        .cloned()
                        {
                            if (is_known_variant(type_summaries.clone(), n.clone())
                                && (is_enum_in_summaries(type_summaries.clone(), n.clone())
                                    == false))
                            {
                                __result.push(n);
                            }
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        __result.push(
                            match reexport_variant_parent_in_import_module(
                                n.clone(),
                                import_module.clone(),
                                registry.clone(),
                                type_summaries.clone(),
                                typed_modules.clone(),
                                export_sets.clone(),
                                source_indices.clone(),
                                module_index.clone(),
                            ) {
                                Some(parent) => parent.clone(),
                                None => "".to_string(),
                            },
                        );
                    }
                    __result
                })
                .iter()
                .cloned()
                {
                    if (p.clone() != "".to_string()) {
                        __result.push(p);
                    }
                }
                __result
            }),
            None => Rc::new(vec![]),
        };
        unique_strings(v1_rt::concat(physical, reexport_parents))
    }
}

