pub fn rhs_base_has_rust_type_authority_in_module(
    mut rhs_name: String,
    mut def_mod_filename: String,
    mut module_name: String,
    mut imports: Rc<Vec<Rc<Node>>>,
    mut scope: Rc<InferScope>,
    mut registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    mut typed_modules: Rc<Vec<Rc<TypedModule>>>,
    mut export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    mut module_index: Rc<ModuleIndex>,
) -> bool {
    loop {
        if is_phantom_unit_variant_type_arg(scope.type_env.clone(), rhs_name.clone()) {
            break true;
        } else {
            match type_item_by_name_in_module_filename(
                rhs_name.clone(),
                def_mod_filename.clone(),
                typed_modules.clone(),
                source_indices.clone(),
                module_index.clone(),
            ) {
                Some(item) => {
                    match module_name_from_filename(
                        def_mod_filename.clone(),
                        typed_modules.clone(),
                        source_indices.clone(),
                        module_index.clone(),
                    ) {
                        Some(def_module_name) => {
                            match typed_module_by_name(
                                def_module_name.clone(),
                                typed_modules.clone(),
                                source_indices.clone(),
                                module_index.clone(),
                            ) {
                                Some(tm) => {
                                    break type_item_has_rust_nominal_shell_authority(
                                        item.clone(),
                                        rhs_name.clone(),
                                        def_module_name.clone(),
                                        module_imports(tm.module.clone()),
                                        module_emit_scope(tm.clone()),
                                        registry,
                                        export_sets.clone(),
                                        typed_modules.clone(),
                                        source_indices.clone(),
                                        module_index.clone(),
                                    );
                                }
                                None => {
                                    break false;
                                }
                            }
                        }
                        None => {
                            break false;
                        }
                    }
                }
                None => {
                    match module_name_from_filename(
                        def_mod_filename.clone(),
                        typed_modules.clone(),
                        source_indices.clone(),
                        module_index.clone(),
                    ) {
                        Some(mod_name) => match v1_rt::map_get(&export_sets, mod_name.clone()) {
                            Some(exported) => {
                                if (v1_rt::map_get(&exported, rhs_name.clone()) == Some(true)) {
                                    match reexport_source_module_name(
                                        rhs_name.clone(),
                                        mod_name.clone(),
                                        typed_modules.clone(),
                                        export_sets.clone(),
                                        source_indices.clone(),
                                        module_index.clone(),
                                    ) {
                                        Some(src) => {
                                            let __tco_0 = module_to_filename(src.clone());
                                            def_mod_filename = __tco_0;
                                            continue;
                                        }
                                        None => {
                                            break false;
                                        }
                                    }
                                } else {
                                    break false;
                                }
                            }
                            None => {
                                break false;
                            }
                        },
                        None => {
                            break false;
                        }
                    }
                }
            }
        }
    }
}

