pub fn rust_pub_use_module_name(line: String) -> String {
    {
        let prefix_parts = Rc::new(
            line.split(&"pub use crate::".to_string())
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
        );
        match prefix_parts.get(1 as usize).cloned() {
            Some(rest) => match Rc::new(
                rest.clone()
                    .split(&"::".to_string())
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>(),
            )
            .first()
            .cloned()
            {
                Some(mod_name) => mod_name.clone(),
                None => "".to_string(),
            },
            None => "".to_string(),
        }
    }
}

pub fn rust_pub_use_singleton_name(line: String) -> String {
    if ((v1_rt::contains(line.clone(), "pub use crate::".to_string())
        && !v1_rt::contains(line.clone(), "::{".to_string()))
        && !v1_rt::contains(line.clone(), "::*;".to_string()))
    {
        {
            let prefix_parts = Rc::new(
                line.clone()
                    .split(&"pub use crate::".to_string())
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>(),
            );
            match prefix_parts.get(1 as usize).cloned() {
                Some(rest) => match Rc::new(
                    rest.clone()
                        .split(&"::".to_string())
                        .map(|s| s.to_string())
                        .collect::<Vec<_>>(),
                )
                .get(1 as usize)
                .cloned()
                {
                    Some(name_part) => match Rc::new(
                        name_part
                            .clone()
                            .split(&";".to_string())
                            .map(|s| s.to_string())
                            .collect::<Vec<_>>(),
                    )
                    .first()
                    .cloned()
                    {
                        Some(name) => name.clone(),
                        None => "".to_string(),
                    },
                    None => "".to_string(),
                },
                None => "".to_string(),
            }
        }
    } else {
        "".to_string()
    }
}

pub fn rust_pub_use_braced_names(line: String) -> Rc<Vec<String>> {
    if (v1_rt::contains(line.clone(), "pub use crate::".to_string())
        && v1_rt::contains(line.clone(), "::{".to_string()))
    {
        {
            let prefix_parts = Rc::new(
                line.clone()
                    .split(&"::{".to_string())
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>(),
            );
            match prefix_parts.get(1 as usize).cloned() {
                Some(rest) => match Rc::new(
                    rest.clone()
                        .split(&"}".to_string())
                        .map(|s| s.to_string())
                        .collect::<Vec<_>>(),
                )
                .first()
                .cloned()
                {
                    Some(names) => Rc::new(
                        names
                            .clone()
                            .split(&", ".to_string())
                            .map(|s| s.to_string())
                            .collect::<Vec<_>>(),
                    ),
                    None => Rc::new(vec![]),
                },
                None => Rc::new(vec![]),
            }
        }
    } else {
        Rc::new(vec![])
    }
}

pub fn rust_pub_use_braced_line_has_name(line: String, mod_name: String, name: String) -> bool {
    (((rust_pub_use_module_name(line.clone()) == mod_name)
        && v1_rt::contains(line.clone(), "::{".to_string()))
        && (((v1_rt::contains(
            line.clone(),
            v1_rt::concat(
                v1_rt::concat("{".to_string(), name.clone()),
                ",".to_string(),
            ),
        ) || v1_rt::contains(
            line.clone(),
            v1_rt::concat(
                v1_rt::concat(", ".to_string(), name.clone()),
                ",".to_string(),
            ),
        )) || v1_rt::contains(
            line.clone(),
            v1_rt::concat(
                v1_rt::concat(", ".to_string(), name.clone()),
                "}".to_string(),
            ),
        )) || v1_rt::contains(
            line.clone(),
            v1_rt::concat(
                v1_rt::concat("{".to_string(), name.clone()),
                "}".to_string(),
            ),
        )))
}

pub fn rust_pub_use_singleton_covered(line: String, lines: Rc<Vec<String>>) -> bool {
    {
        let mod_name = rust_pub_use_module_name(line.clone());
        let name = rust_pub_use_singleton_name(line.clone());
        if ((mod_name.clone() == "".to_string()) || (name.clone() == "".to_string())) {
            false
        } else {
            {
                let mut __found = false;
                for other in lines.iter().cloned() {
                    if rust_pub_use_braced_line_has_name(
                        other.clone(),
                        mod_name.clone(),
                        name.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    }
}

pub fn rust_pub_use_braced_subset_covered(line: String, lines: Rc<Vec<String>>) -> bool {
    {
        let mod_name = rust_pub_use_module_name(line.clone());
        let names = rust_pub_use_braced_names(line.clone());
        if ((mod_name.clone() == "".to_string()) || ((names.clone().len() as i64) == 0)) {
            false
        } else {
            {
                let mut __found = false;
                for other in lines.iter().cloned() {
                    if (((((other.clone() != line.clone())
                        && (rust_pub_use_module_name(other.clone()) == mod_name.clone()))
                        && v1_rt::contains(other.clone(), "::{".to_string()))
                        && ((rust_pub_use_braced_names(other.clone()).len() as i64)
                            > (names.clone().len() as i64)))
                        && {
                            let mut __all = true;
                            for name in names.clone().iter().cloned() {
                                if !(rust_pub_use_braced_line_has_name(
                                    other.clone(),
                                    mod_name.clone(),
                                    name.clone(),
                                )) {
                                    __all = false;
                                    break;
                                }
                            }
                            __all
                        })
                    {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct BracedImportCoverAccum {
    pub found_current: bool,
    pub covered: bool,
}

pub fn rust_pub_use_braced_equal_prior_covered(line: String, lines: Rc<Vec<String>>) -> bool {
    {
        let mod_name = rust_pub_use_module_name(line.clone());
        let names = rust_pub_use_braced_names(line.clone());
        if ((mod_name.clone() == "".to_string()) || ((names.clone().len() as i64) == 0)) {
            false
        } else {
            {
                let acc = lines.iter().cloned().fold(
                    BracedImportCoverAccum {
                        found_current: false,
                        covered: false,
                    },
                    |inner: BracedImportCoverAccum, other: String| {
                        if (inner.found_current.clone() || inner.covered.clone()) {
                            inner.clone()
                        } else {
                            if (other.clone() == line.clone()) {
                                BracedImportCoverAccum {
                                    found_current: true,
                                    covered: inner.covered.clone(),
                                }
                            } else {
                                {
                                    let other_names = rust_pub_use_braced_names(other.clone());
                                    let is_equal_cover =
                                        ((((rust_pub_use_module_name(other.clone())
                                            == mod_name.clone())
                                            && v1_rt::contains(other.clone(), "::{".to_string()))
                                            && ((other_names.clone().len() as i64)
                                                == (names.clone().len() as i64)))
                                            && {
                                                let mut __all = true;
                                                for name in names.clone().iter().cloned() {
                                                    if !(rust_pub_use_braced_line_has_name(
                                                        other.clone(),
                                                        mod_name.clone(),
                                                        name.clone(),
                                                    )) {
                                                        __all = false;
                                                        break;
                                                    }
                                                }
                                                __all
                                            });
                                    BracedImportCoverAccum {
                                        found_current: false,
                                        covered: is_equal_cover.clone(),
                                    }
                                }
                            }
                        }
                    },
                );
                acc.covered.clone()
            }
        }
    }
}

pub fn dedupe_rust_import_lines(lines: Rc<Vec<String>>) -> Rc<Vec<String>> {
    {
        let exact = unique_strings(Rc::new({
            let mut __result = Vec::new();
            for line in lines.iter().cloned() {
                if (line.clone() != "".to_string()) {
                    __result.push(line);
                }
            }
            __result
        }));
        Rc::new({
            let mut __result = Vec::new();
            for line in exact.clone().iter().cloned() {
                if (((rust_pub_use_singleton_covered(line.clone(), exact.clone()) == false)
                    && (rust_pub_use_braced_subset_covered(line.clone(), exact.clone()) == false))
                    && (rust_pub_use_braced_equal_prior_covered(line.clone(), exact.clone())
                        == false))
                {
                    __result.push(line);
                }
            }
            __result
        })
    }
}

pub fn emit_imports(
    imports: Rc<Vec<Rc<Node>>>,
    emit_info: Rc<EmitGraphInfo>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    local_names: Rc<Vec<String>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    module_index: Rc<ModuleIndex>,
) -> String {
    if ((imports.clone().len() as i64) == 0) {
        "".to_string()
    } else {
        {
            let import_modules = unique_strings(Rc::new({
                let mut __result = Vec::new();
                for imp in imports.clone().iter().cloned() {
                    __result.push(authored_name_at(source_indices.clone(), imp.clone()));
                }
                __result
            }));
            let import_lines = Rc::new({
                let mut __result = Vec::new();
                for import_module in import_modules.iter().cloned() {
                    __result.extend(
                        (*{
                            let mod_imports = Rc::new({
                                let mut __result = Vec::new();
                                for imp in imports.clone().iter().cloned() {
                                    if (authored_name_at(source_indices.clone(), imp.clone())
                                        == import_module.clone())
                                    {
                                        __result.push(imp);
                                    }
                                }
                                __result
                            });
                            let mod_name = module_to_filename(import_module.clone());
                            let block = if {
                                let mut __found = false;
                                for imp in mod_imports.clone().iter().cloned() {
                                    if import_is_all(imp.clone()) {
                                        __found = true;
                                        break;
                                    }
                                }
                                __found
                            } {
                                {
                                    let wildcard_line = v1_rt::concat(
                                        v1_rt::concat("use crate::".to_string(), mod_name.clone()),
                                        "::*;".to_string(),
                                    );
                                    let reexport_surface = wildcard_reexport_surface_names(
                                        import_module.clone(),
                                        export_sets.clone(),
                                        typed_modules.clone(),
                                        source_indices.clone(),
                                        module_index.clone(),
                                    );
                                    let merged_specific = unique_strings(v1_rt::concat(
                                        Rc::new({
                                            let mut __result = Vec::new();
                                            for imp in Rc::new({
                                                let mut __result = Vec::new();
                                                for imp in mod_imports.clone().iter().cloned() {
                                                    if (import_is_all(imp.clone()) == false) {
                                                        __result.push(imp);
                                                    }
                                                }
                                                __result
                                            })
                                            .iter()
                                            .cloned()
                                            {
                                                __result.extend(
                                                    (*import_specific_names_at(
                                                        imp.clone(),
                                                        source_indices.clone(),
                                                    ))
                                                    .iter()
                                                    .cloned(),
                                                );
                                            }
                                            __result
                                        }),
                                        reexport_surface.clone(),
                                    ));
                                    let specific_block = emit_specific_import_block(
                                        import_module.clone(),
                                        mod_name.clone(),
                                        merged_specific.clone(),
                                        emit_info.clone(),
                                        registry.clone(),
                                        local_names.clone(),
                                        export_sets.clone(),
                                        typed_modules.clone(),
                                        source_indices.clone(),
                                        module_index.clone(),
                                    );
                                    if (specific_block.clone() != "".to_string()) {
                                        v1_rt::concat(
                                            v1_rt::concat(wildcard_line.clone(), "\n".to_string()),
                                            specific_block.clone(),
                                        )
                                    } else {
                                        wildcard_line.clone()
                                    }
                                }
                            } else {
                                {
                                    let specific_names = Rc::new({
                                        let mut __result = Vec::new();
                                        for imp in mod_imports.clone().iter().cloned() {
                                            __result.extend(
                                                (*import_specific_names_at(
                                                    imp.clone(),
                                                    source_indices.clone(),
                                                ))
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    });
                                    let merged_specific = unique_strings(specific_names.clone());
                                    emit_specific_import_block(
                                        import_module.clone(),
                                        mod_name.clone(),
                                        merged_specific.clone(),
                                        emit_info.clone(),
                                        registry.clone(),
                                        local_names.clone(),
                                        export_sets.clone(),
                                        typed_modules.clone(),
                                        source_indices.clone(),
                                        module_index.clone(),
                                    )
                                }
                            };
                            Rc::new(
                                block
                                    .clone()
                                    .split(&"\n".to_string())
                                    .map(|s| s.to_string())
                                    .collect::<Vec<_>>(),
                            )
                        })
                        .iter()
                        .cloned(),
                    );
                }
                __result
            });
            dedupe_rust_import_lines(import_lines).join(&"\n".to_string())
        }
    }
}

pub fn emit_prelude(imported_names: Rc<Vec<String>>) -> String {
    {
        let base = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    "use std::collections::BTreeSet;\n".to_string(),
                    "use std::collections::HashMap;\n".to_string(),
                ),
                "use std::rc::Rc;\n".to_string(),
            ),
            "use crate::v1_rt;".to_string(),
        );
        let has_witness = {
            let mut __found = false;
            for n in imported_names.clone().iter().cloned() {
                if (n.clone() == "Witness".to_string()) {
                    __found = true;
                    break;
                }
            }
            __found
        };
        let has_holds = {
            let mut __found = false;
            for n in imported_names.clone().iter().cloned() {
                if (n.clone() == "Holds".to_string()) {
                    __found = true;
                    break;
                }
            }
            __found
        };
        let has_violates = {
            let mut __found = false;
            for n in imported_names.clone().iter().cloned() {
                if (n.clone() == "Violates".to_string()) {
                    __found = true;
                    break;
                }
            }
            __found
        };
        let witness_line = if ((has_witness || has_holds.clone()) || has_violates.clone()) {
            "".to_string()
        } else {
            "\nuse crate::v1_rt::Witness;".to_string()
        };
        let variant_line = if (has_holds.clone() && has_violates.clone()) {
            "".to_string()
        } else {
            if has_holds.clone() {
                "\nuse crate::v1_rt::Witness::Violates;".to_string()
            } else {
                if has_violates.clone() {
                    "\nuse crate::v1_rt::Witness::Holds;".to_string()
                } else {
                    "\nuse crate::v1_rt::Witness::{Holds, Violates};".to_string()
                }
            }
        };
        let wrapper_use = "\nuse crate::NonEmptyVec;\nuse crate::NonEmptyBTreeSet;".to_string();
        v1_rt::concat(
            v1_rt::concat(v1_rt::concat(base, witness_line), variant_line),
            wrapper_use,
        )
    }
}

pub fn emit_non_empty_wrappers() -> String {
    {
        let vec_wrapper = v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("#[derive(Debug, Clone, PartialEq)]\n".to_string(), "pub struct NonEmptyVec<T>(Vec<T>);\n\n".to_string()), "impl<T> NonEmptyVec<T> {\n".to_string()), "    pub fn new(items: Vec<T>) -> Result<Self, &'static str> {\n".to_string()), "        if items.is_empty() {\n".to_string()), "            Err(\"NonEmptyVec requires at least one element\")\n".to_string()), "        } else {\n".to_string()), "            Ok(Self(items))\n".to_string()), "        }\n".to_string()), "    }\n\n".to_string()), "    pub fn as_slice(&self) -> &[T] {\n".to_string()), "        &self.0\n".to_string()), "    }\n\n".to_string()), "    pub fn into_vec(self) -> Vec<T> {\n".to_string()), "        self.0\n".to_string()), "    }\n".to_string()), "}".to_string());
        let set_wrapper = v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("#[derive(Debug, Clone, PartialEq)]\n".to_string(), "pub struct NonEmptyBTreeSet<T: Ord>(std::collections::BTreeSet<T>);\n\n".to_string()), "impl<T: Ord> NonEmptyBTreeSet<T> {\n".to_string()), "    pub fn new(items: std::collections::BTreeSet<T>) -> Result<Self, &'static str> {\n".to_string()), "        if items.is_empty() {\n".to_string()), "            Err(\"NonEmptyBTreeSet requires at least one element\")\n".to_string()), "        } else {\n".to_string()), "            Ok(Self(items))\n".to_string()), "        }\n".to_string()), "    }\n\n".to_string()), "    pub fn as_set(&self) -> &std::collections::BTreeSet<T> {\n".to_string()), "        &self.0\n".to_string()), "    }\n\n".to_string()), "    pub fn into_set(self) -> std::collections::BTreeSet<T> {\n".to_string()), "        self.0\n".to_string()), "    }\n".to_string()), "}".to_string());
        v1_rt::concat(v1_rt::concat(vec_wrapper, "\n\n".to_string()), set_wrapper)
    }
}

pub fn emit_typed_item(
    item: Rc<Node>,
    module_name: String,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
    wire_contract_item: Option<Rc<Node>>,
    data_items: Rc<HashMap<String, Rc<Vec<Rc<Node>>>>>,
    module_items: Rc<Vec<Rc<Node>>>,
    imports: Rc<Vec<Rc<Node>>>,
    export_sets: Rc<HashMap<String, Rc<HashMap<String, bool>>>>,
    typed_modules: Rc<Vec<Rc<TypedModule>>>,
    module_index: Rc<ModuleIndex>,
) -> String {
    {
        let env = (*scope.type_env).clone();
        let qualified_name = v1_rt::concat(
            v1_rt::concat(module_name.clone(), ".".to_string()),
            authored_name(Rc::new(env.clone()), item.clone()),
        );
        let item_text = authored_name(Rc::new(env.clone()), item.clone());
        if is_type_def_item(item.clone()) {
            emit_type_def_from_connective(
                item.clone(),
                emit_info.recursive_type_set.clone(),
                shared_types,
                Rc::new(env.clone()),
                emit_info.clone(),
                wire_contract_item,
                data_items,
                module_items,
                imports.clone(),
            )
        } else {
            if is_type_alias_item(item.clone(), env.source_indices.clone()) {
                if (corpus_repr_is_host(emit_info.corpus_repr.clone())
                    && (item_text.clone() == "String".to_string()))
                {
                    v1_rt::concat(
                        v1_rt::concat(
                            rust_visibility_prefix(),
                            rust_items().type_alias_keyword.clone(),
                        ),
                        " String = std::string::String;".to_string(),
                    )
                } else {
                    if (((item.params.clone().len() as i64) == 0)
                        && rust_nominal_identity_carrier_type_eligible(item_text.clone()))
                    {
                        rust_nominal_identity_carrier_def(item_text.clone())
                    } else {
                        if is_zero_param_self_referential_opaque_decl(
                            item.clone(),
                            env.source_indices.clone(),
                        ) {
                            emit_zero_param_phantom_opaque_struct(
                                item.clone(),
                                env.source_indices.clone(),
                            )
                        } else {
                            match rust_seed_host_numeric_alias(
                                item_text.clone(),
                                emit_info.corpus_repr.clone(),
                            ) {
                                Some(host) => v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        rust_visibility_prefix(),
                                                        rust_items().type_alias_keyword.clone(),
                                                    ),
                                                    " ".to_string(),
                                                ),
                                                item_text.clone(),
                                            ),
                                            " = ".to_string(),
                                        ),
                                        host.clone(),
                                    ),
                                    ";".to_string(),
                                ),
                                None => v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        rust_visibility_prefix(),
                                                        rust_items().type_alias_keyword.clone(),
                                                    ),
                                                    " ".to_string(),
                                                ),
                                                item_text.clone(),
                                            ),
                                            " = ".to_string(),
                                        ),
                                        render_rust_alias_rhs_type(
                                            resolved_type(item.clone()),
                                            Rc::new(vec![]),
                                            shared_types,
                                            emit_info.corpus_repr.clone(),
                                            env.source_indices.clone(),
                                            scope.clone(),
                                            imports.clone(),
                                            registry.clone(),
                                            module_name.clone(),
                                            export_sets.clone(),
                                            typed_modules.clone(),
                                            module_index.clone(),
                                            emit_info.variant_to_enum.clone(),
                                        ),
                                    ),
                                    ";".to_string(),
                                ),
                            }
                        }
                    }
                }
            } else {
                if is_type_decl_item(item.clone(), env.source_indices.clone()) {
                    if (((item.params.clone().len() as i64) == 0)
                        && rust_nominal_identity_carrier_type_eligible(item_text.clone()))
                    {
                        rust_nominal_identity_carrier_def(item_text.clone())
                    } else {
                        match rust_seed_host_container_base(
                            item_text.clone(),
                            emit_info.corpus_repr.clone(),
                        ) {
                            Some(host) => {
                                let type_params = emit_type_params(
                                    item.params.clone(),
                                    env.source_indices.clone(),
                                );
                                let generic_names = item_generic_param_names(
                                    item.clone(),
                                    env.source_indices.clone(),
                                );
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                v1_rt::concat(
                                                                    rust_visibility_prefix(),
                                                                    rust_items()
                                                                        .type_alias_keyword
                                                                        .clone(),
                                                                ),
                                                                " ".to_string(),
                                                            ),
                                                            item_text.clone(),
                                                        ),
                                                        type_params,
                                                    ),
                                                    " = ".to_string(),
                                                ),
                                                host.clone(),
                                            ),
                                            "<".to_string(),
                                        ),
                                        Rc::new({
                                            let mut __result = Vec::new();
                                            for n in generic_names.clone().iter().cloned() {
                                                __result.push(to_pascal(n.clone()));
                                            }
                                            __result
                                        })
                                        .join(&", ".to_string()),
                                    ),
                                    ">;".to_string(),
                                )
                            }
                            None => {
                                if is_emittable_parametric_type_alias_item(
                                    item.clone(),
                                    item_text.clone(),
                                    env.source_indices.clone(),
                                    module_name.clone(),
                                    imports.clone(),
                                    scope.clone(),
                                    registry.clone(),
                                    export_sets.clone(),
                                    typed_modules.clone(),
                                    module_index.clone(),
                                ) {
                                    {
                                        let type_params = emit_type_params(
                                            item.params.clone(),
                                            env.source_indices.clone(),
                                        );
                                        let generic_names = item_generic_param_names(
                                            item.clone(),
                                            env.source_indices.clone(),
                                        );
                                        let alias_rhs = resolved_type(item.clone());
                                        let unused_params = alias_unused_param_names(
                                            generic_names.clone(),
                                            alias_rhs.clone(),
                                            env.source_indices.clone(),
                                        );
                                        let rhs_str = if ((unused_params.clone().len() as i64) > 0)
                                        {
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    "std::marker::PhantomData<".to_string(),
                                                    rust_phantom_marker_inner(
                                                        unused_params.clone(),
                                                    ),
                                                ),
                                                ">".to_string(),
                                            )
                                        } else {
                                            render_rust_alias_rhs_type(
                                                alias_rhs.clone(),
                                                generic_names.clone(),
                                                shared_types,
                                                emit_info.corpus_repr.clone(),
                                                env.source_indices.clone(),
                                                scope.clone(),
                                                imports.clone(),
                                                registry.clone(),
                                                module_name.clone(),
                                                export_sets.clone(),
                                                typed_modules.clone(),
                                                module_index.clone(),
                                                emit_info.variant_to_enum.clone(),
                                            )
                                        };
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                v1_rt::concat(
                                                                    rust_visibility_prefix(),
                                                                    rust_items()
                                                                        .type_alias_keyword
                                                                        .clone(),
                                                                ),
                                                                " ".to_string(),
                                                            ),
                                                            item_text.clone(),
                                                        ),
                                                        type_params,
                                                    ),
                                                    " = ".to_string(),
                                                ),
                                                rhs_str,
                                            ),
                                            ";".to_string(),
                                        )
                                    }
                                } else {
                                    if is_parametric_opaque_type_decl_item(
                                        item.clone(),
                                        env.source_indices.clone(),
                                    ) {
                                        emit_parametric_phantom_opaque_struct(
                                            item.clone(),
                                            env.source_indices.clone(),
                                        )
                                    } else {
                                        "".to_string()
                                    }
                                }
                            }
                        }
                    }
                } else {
                    if is_function_item(item.clone()) {
                        {
                            let fn_movable = match v1_rt::map_get(
                                &emit_info.ownership_index.clone(),
                                qualified_name.clone(),
                            ) {
                                Some(m) => m.clone(),
                                None => v1_rt::rc_empty_set::<String>(),
                            };
                            let item_is_tco = is_tco_eligible(
                                authored_name(Rc::new(env.clone()), item.clone()),
                                item.body.clone().clone().unwrap(),
                                registry.clone(),
                                env.source_indices.clone(),
                            );
                            let fn_read_only = if item_is_tco.clone() {
                                v1_rt::rc_empty_set::<String>()
                            } else {
                                match v1_rt::map_get(
                                    &emit_info.read_only_params_index.clone(),
                                    qualified_name.clone(),
                                ) {
                                    Some(m) => m.clone(),
                                    None => v1_rt::rc_empty_set::<String>(),
                                }
                            };
                            let fn_move_sites = if item_is_tco.clone() {
                                v1_rt::rc_empty_map::<String, bool>()
                            } else {
                                match v1_rt::map_get(
                                    &emit_info.move_sites_index.clone(),
                                    qualified_name.clone(),
                                ) {
                                    Some(m) => m.clone(),
                                    None => v1_rt::rc_empty_map::<String, bool>(),
                                }
                            };
                            let fn_emit_info = Rc::new(EmitGraphInfo {
                                type_summaries: emit_info.type_summaries.clone(),
                                recursive_type_set: emit_info.recursive_type_set.clone(),
                                fielded_variants: emit_info.fielded_variants.clone(),
                                positional_payload_variants: emit_info
                                    .positional_payload_variants
                                    .clone(),
                                shared_types: emit_info.shared_types.clone(),
                                ownership_index: emit_info.ownership_index.clone(),
                                movable: fn_movable,
                                variant_to_enum: emit_info.variant_to_enum.clone(),
                                owned_bindings: v1_rt::rc_empty_set::<String>(),
                                move_sites_index: emit_info.move_sites_index.clone(),
                                move_sites: fn_move_sites,
                                read_only_params_index: emit_info.read_only_params_index.clone(),
                                read_only_params: fn_read_only,
                                corpus_repr: emit_info.corpus_repr.clone(),
                            });
                            let is_effectful = match lookup_item(
                                registry.clone(),
                                authored_name(Rc::new(env.clone()), item.clone()),
                            ) {
                                Some(info) => {
                                    (((info.service_names.clone().len() as i64) > 0)
                                        || ((info.resource_names.clone().len() as i64) > 0))
                                }
                                None => false,
                            };
                            if is_effectful {
                                emit_func_def(
                                    item_text.clone(),
                                    item.params.clone(),
                                    resolved_type(item.clone()),
                                    item.uses.clone(),
                                    item.body.clone().clone().unwrap(),
                                    registry.clone(),
                                    scope.clone(),
                                    shared_types,
                                    fn_emit_info,
                                )
                            } else {
                                emit_fn_def(
                                    item_text.clone(),
                                    item.params.clone(),
                                    resolved_type(item.clone()),
                                    item.body.clone().clone().unwrap(),
                                    registry.clone(),
                                    scope.clone(),
                                    shared_types,
                                    fn_emit_info,
                                )
                            }
                        }
                    } else {
                        if is_data_def_item(item.clone()) {
                            emit_data_def(
                                item_text.clone(),
                                item.type_annotation.clone().clone().unwrap(),
                                item.body.clone().clone().unwrap(),
                                registry.clone(),
                                scope.clone(),
                                0,
                                shared_types,
                                emit_info.clone(),
                            )
                        } else {
                            if is_service_def_item(item.clone()) {
                                emit_service_def(
                                    item.clone(),
                                    registry.clone(),
                                    shared_types,
                                    emit_info.corpus_repr.clone(),
                                    Rc::new(env.clone()),
                                )
                            } else {
                                if is_resource_def_item(item.clone()) {
                                    emit_resource_def(
                                        item.clone(),
                                        shared_types,
                                        emit_info.corpus_repr.clone(),
                                        Rc::new(env.clone()),
                                    )
                                } else {
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            "compile_error!(\"unhandled item: ".to_string(),
                                            item_text.clone(),
                                        ),
                                        "\");".to_string(),
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn needs_box_wrapping_shared_dominates() -> String {
    thread_local! {
        static CACHED: String = {
            "A shared (Rc-rendered) type NEVER needs Box: Rc is already the cycle-breaking indirection, so Box<Rc<T>> is a double wrap that no committed seed ever carried. shared_types must dominate the recursive_types check — the old ordering short-circuited recursive->Box first, which was benign only while emit-time recursive_types stayed module-local; once build_type_env propagated imported recursive types (B1), every Rc field of Node/TypeEnv/... would have double-wrapped.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn needs_box_wrapping(
    mut n: Rc<Node>,
    mut recursive_types: Rc<std::collections::BTreeSet<String>>,
    mut shared_types: Rc<std::collections::BTreeSet<String>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        let name = authored_name_at(source_indices.clone(), n.clone());
        if v1_rt::set_contains(&shared_types, name.clone()) {
            break false;
        } else {
            if v1_rt::set_contains(&recursive_types, name.clone()) {
                break true;
            } else {
                if ((n.children.clone().len() as i64) == 0) {
                    if (coerce_primitive_type(RenderTarget::Rust, name.clone()) != name.clone()) {
                        break false;
                    } else {
                        break v1_rt::set_contains(&recursive_types, name.clone());
                    }
                } else {
                    let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
                    if is_optional {
                        {
                            let __tco_0 = with_required_cardinality(n);
                            n = __tco_0;
                            continue;
                        }
                    } else {
                        break false;
                    }
                }
            }
        }
    }
}

pub fn emit_type_params(
    params: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    if ((params.clone().len() as i64) == 0) {
        "".to_string()
    } else {
        {
            let names = Rc::new({
                let mut __result = Vec::new();
                for p in params.clone().iter().cloned() {
                    __result.push(to_pascal(generic_param_name_at(
                        p.clone(),
                        source_indices.clone(),
                    )));
                }
                __result
            });
            v1_rt::concat(
                v1_rt::concat("<".to_string(), names.join(&", ".to_string())),
                ">".to_string(),
            )
        }
    }
}

pub fn emit_type_params_with_clone_bound(
    params: Rc<Vec<Rc<Node>>>,
    clone_param: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    if ((params.clone().len() as i64) == 0) {
        "".to_string()
    } else {
        {
            let names = Rc::new({
                let mut __result = Vec::new();
                for p in params.clone().iter().cloned() {
                    __result.push({
                        let pname = generic_param_name_at(p.clone(), source_indices.clone());
                        let pascal = to_pascal(pname.clone());
                        if (pname.clone() == clone_param.clone()) {
                            v1_rt::concat(pascal.clone(), ": Clone".to_string())
                        } else {
                            pascal.clone()
                        }
                    });
                }
                __result
            });
            v1_rt::concat(
                v1_rt::concat("<".to_string(), names.join(&", ".to_string())),
                ">".to_string(),
            )
        }
    }
}

pub fn is_function_type_param(param: Rc<Node>) -> bool {
    {
        let type_expr = param_node_type_expr(param.clone());
        let type_expr_is_var = match type_expr.inferred.clone() {
            Some(inf) => is_type_variable(inf.clone()),
            None => false,
        };
        let same_source_span = (((param.span.clone().file.clone()
            == type_expr.span.clone().file.clone())
            && (param.span.clone().start.clone() == type_expr.span.clone().start.clone()))
            && (param.span.clone().end.clone() == type_expr.span.clone().end.clone()));
        (((param.name.clone() != "".to_string()) && (param.name.clone() == type_expr.name.clone()))
            && (type_expr_is_var || same_source_span))
    }
}

pub fn function_type_params(params: Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<Node>>> {
    Rc::new({
        let mut __result = Vec::new();
        for p in params.iter().cloned() {
            if is_function_type_param(p.clone()) {
                __result.push(p);
            }
        }
        __result
    })
}

pub fn function_value_params(params: Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<Node>>> {
    Rc::new({
        let mut __result = Vec::new();
        for p in params.iter().cloned() {
            if !is_function_type_param(p.clone()) {
                __result.push(p);
            }
        }
        __result
    })
}

pub fn function_type_params_have_collision(type_params: Rc<Vec<Rc<Node>>>) -> bool {
    {
        let names = Rc::new({
            let mut __result = Vec::new();
            for p in type_params.iter().cloned() {
                __result.push(p.name.clone());
            }
            __result
        });
        ((names.clone().len() as i64) > (unique_strings(names.clone()).len() as i64))
    }
}

pub fn emit_type_def_from_connective(
    item: Rc<Node>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    emit_info: Rc<EmitGraphInfo>,
    wire_contract_item: Option<Rc<Node>>,
    data_items: Rc<HashMap<String, Rc<Vec<Rc<Node>>>>>,
    module_items: Rc<Vec<Rc<Node>>>,
    imports: Rc<Vec<Rc<Node>>>,
) -> String {
    {
        let type_params = emit_type_params(item.params.clone(), env.source_indices.clone());
        let item_text = authored_name(env.clone(), item.clone());
        let is_product = is_product_type(item.clone());
        if is_product {
            {
                let generic_param_names = Rc::new({
                    let mut __result = Vec::new();
                    for p in item.params.clone().iter().cloned() {
                        __result.push(generic_param_name_at(p.clone(), env.source_indices.clone()));
                    }
                    __result
                });
                emit_struct_from_children(
                    item_text.clone(),
                    type_params,
                    generic_param_names,
                    item.children.clone(),
                    recursive_types,
                    shared_types,
                    env.clone(),
                    emit_info.clone(),
                )
            }
        } else {
            if is_host_freemonoid_vec_alias(item_text.clone(), emit_info.corpus_repr.clone()) {
                {
                    let elem_csv = Rc::new({
                        let mut __result = Vec::new();
                        for p in item.params.clone().iter().cloned() {
                            __result.push(to_pascal(generic_param_name_at(
                                p.clone(),
                                env.source_indices.clone(),
                            )));
                        }
                        __result
                    })
                    .join(&", ".to_string());
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            rust_visibility_prefix(),
                                            "type ".to_string(),
                                        ),
                                        item_text.clone(),
                                    ),
                                    type_params,
                                ),
                                " = Vec<".to_string(),
                            ),
                            elem_csv,
                        ),
                        ">;".to_string(),
                    )
                }
            } else {
                {
                    let all_unit_variants = {
                        let mut __all = true;
                        for child in item.children.clone().iter().cloned() {
                            if !((child.children.clone().len() as i64) == 0) {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    };
                    let serde_policy = match resolve_local_coproduct_wire_policy(
                        item_text.clone(),
                        all_unit_variants.clone(),
                        module_items,
                        imports,
                        env.source_indices.clone(),
                    ) {
                        Some(local_policy) => local_policy.clone(),
                        None => {
                            if all_unit_variants.clone() {
                                match wire_contract_item.clone() {
                                    Some(_) => resolve_wire_serde_policy_for_coproduct(
                                        wire_contract_item.clone(),
                                        env.source_indices.clone(),
                                        data_items,
                                    ),
                                    None => rust_tagged_object_policy(),
                                }
                            } else {
                                rust_tagged_object_policy()
                            }
                        }
                    };
                    let rename_validations = variant_rename_validations_for_policy(
                        item.children.clone(),
                        env.clone(),
                        serde_policy.clone(),
                    );
                    let policy_validation = match serde_policy.error_message.clone() {
                        Some(message) => emit_rust_compile_error_item(message.clone()),
                        None => "".to_string(),
                    };
                    let validations = if (policy_validation.clone() == "".to_string()) {
                        rename_validations.clone()
                    } else {
                        if (rename_validations.clone() == "".to_string()) {
                            policy_validation.clone()
                        } else {
                            v1_rt::concat(
                                v1_rt::concat(policy_validation.clone(), "\n".to_string()),
                                rename_validations.clone(),
                            )
                        }
                    };
                    let generic_param_names = Rc::new({
                        let mut __result = Vec::new();
                        for p in item.params.clone().iter().cloned() {
                            __result
                                .push(generic_param_name_at(p.clone(), env.source_indices.clone()));
                        }
                        __result
                    });
                    let enum_text = emit_enum_from_children(
                        item_text.clone(),
                        type_params,
                        generic_param_names,
                        item.children.clone(),
                        recursive_types,
                        shared_types,
                        env.clone(),
                        serde_policy.clone(),
                        emit_info.clone(),
                    );
                    if (validations.clone() == "".to_string()) {
                        enum_text
                    } else {
                        v1_rt::concat(
                            v1_rt::concat(validations.clone(), "\n".to_string()),
                            enum_text,
                        )
                    }
                }
            }
        }
    }
}

pub fn type_node_mentions_name(
    n: Rc<Node>,
    target: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (authored_name_at(source_indices.clone(), n.clone()) == target.clone()) {
            true
        } else {
            {
                let mut __found = false;
                for c in n.children.clone().iter().cloned() {
                    if type_node_mentions_name(c.clone(), target.clone(), source_indices.clone()) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    })
}

pub fn struct_unused_param_names(
    generic_param_names: Rc<Vec<String>>,
    children: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for p in generic_param_names.iter().cloned() {
            if !{
                let mut __found = false;
                for child in children.clone().iter().cloned() {
                    if type_node_mentions_name(
                        field_node_type_expr(child.clone()),
                        p.clone(),
                        source_indices.clone(),
                    ) {
                        __found = true;
                        break;
                    }
                }
                __found
            } {
                __result.push(p);
            }
        }
        __result
    })
}

pub fn alias_unused_param_names(
    generic_param_names: Rc<Vec<String>>,
    rhs: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    Rc::new({
        let mut __result = Vec::new();
        for p in generic_param_names.iter().cloned() {
            if !type_node_mentions_name(rhs.clone(), p.clone(), source_indices.clone()) {
                __result.push(p);
            }
        }
        __result
    })
}

pub fn rust_phantom_marker_inner(unused: Rc<Vec<String>>) -> String {
    {
        let pascal_unused = Rc::new({
            let mut __result = Vec::new();
            for n in unused.iter().cloned() {
                __result.push(to_pascal(n.clone()));
            }
            __result
        });
        if ((pascal_unused.clone().len() as i64) == 1) {
            pascal_unused.clone().join(&", ".to_string())
        } else {
            v1_rt::concat(
                v1_rt::concat(
                    "(".to_string(),
                    pascal_unused.clone().join(&", ".to_string()),
                ),
                ")".to_string(),
            )
        }
    }
}

pub fn rust_phantom_field_name() -> String {
    "_phantom".to_string()
}

pub fn emit_struct_from_children(
    name: String,
    type_params: String,
    generic_param_names: Rc<Vec<String>>,
    children: Rc<Vec<Rc<Node>>>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let has_fn_fields = match v1_rt::map_get(&emit_info.type_summaries.clone(), name.clone()) {
            Some(ts) => ts.has_fn_fields.clone(),
            None => false,
        };
        let derives = if has_fn_fields {
            "#[derive(Clone)]".to_string()
        } else {
            if (rust_nominal_ord_derives_for_shape(
                name.clone(),
                children.clone(),
                env.source_indices.clone(),
            ) != "".to_string())
            {
                rust_nominal_ord_derives_for_shape(
                    name.clone(),
                    children.clone(),
                    env.source_indices.clone(),
                )
            } else {
                if v1_rt::set_contains(&shared_types, name.clone()) {
                    rust_struct_derives_text()
                } else {
                    rust_struct_derives_copy_text()
                }
            }
        };
        if ((children.clone().len() as i64) == 0) {
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(derives, "\n".to_string()),
                                    rust_visibility_prefix(),
                                ),
                                rust_items().struct_keyword.clone(),
                            ),
                            " ".to_string(),
                        ),
                        name.clone(),
                    ),
                    type_params,
                ),
                ";".to_string(),
            )
        } else {
            {
                let field_lines = Rc::new({
                    let mut __result = Vec::new();
                    for child in children.clone().iter().cloned() {
                        __result.push(emit_struct_field_from_child(
                            name.clone(),
                            child.clone(),
                            generic_param_names.clone(),
                            recursive_types.clone(),
                            shared_types.clone(),
                            env.clone(),
                            emit_info.clone(),
                        ));
                    }
                    __result
                });
                let unused_params = struct_unused_param_names(
                    generic_param_names.clone(),
                    children.clone(),
                    env.source_indices.clone(),
                );
                let all_field_lines = if ((unused_params.clone().len() as i64) > 0) {
                    v1_rt::concat(
                        field_lines,
                        Rc::new(vec![v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat("    ".to_string(), rust_visibility_prefix()),
                                        rust_phantom_field_name(),
                                    ),
                                    ": std::marker::PhantomData<".to_string(),
                                ),
                                rust_phantom_marker_inner(unused_params.clone()),
                            ),
                            ">,".to_string(),
                        )]),
                    )
                } else {
                    field_lines
                };
                let fields_str = all_field_lines.join(&"\n".to_string());
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(derives, "\n".to_string()),
                                                rust_visibility_prefix(),
                                            ),
                                            rust_items().struct_keyword.clone(),
                                        ),
                                        " ".to_string(),
                                    ),
                                    name.clone(),
                                ),
                                type_params,
                            ),
                            " {\n".to_string(),
                        ),
                        fields_str,
                    ),
                    "\n}".to_string(),
                )
            }
        }
    }
}

pub fn render_rust_type_with_applied_binding(
    n: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        if is_host_text_carrier_type(n.clone(), source_indices.clone(), corpus_repr.clone()) {
            return rust_carrier_optional_wrap(n.clone(), "String".to_string());
        }
        match find_property(
            n.properties.clone(),
            "__applied_type_args".to_string(),
            source_indices.clone(),
        ) {
            Some(applied) => {
                if ((applied.children.clone().len() as i64) > 0) {
                    {
                        let outer_name = authored_name_at(source_indices.clone(), n.clone());
                        let applied_name =
                            authored_name_at(source_indices.clone(), applied.clone());
                        if (((outer_name.clone() != "".to_string())
                            && (n.connective.clone() == Connective::NoConnective))
                            && ((n.children.clone().len() as i64) == 0))
                        {
                            if (outer_name.clone() != applied_name) {
                                render_rust_shared_type_if_needed(
                                    outer_name.clone(),
                                    outer_name.clone(),
                                    shared_types.clone(),
                                )
                            } else {
                                if v1_rt::set_contains(&shared_types, outer_name.clone()) {
                                    render_rust_shared_type_if_needed(
                                        outer_name.clone(),
                                        outer_name.clone(),
                                        shared_types.clone(),
                                    )
                                } else {
                                    render_rust_applied_type_shared(
                                        applied.clone(),
                                        Rc::new(vec![]),
                                        shared_types.clone(),
                                        corpus_repr.clone(),
                                        source_indices.clone(),
                                        v1_rt::rc_empty_map::<String, String>(),
                                        Rc::new(TypeEnv {
                                            bindings: v1_rt::rc_empty_map::<i64, Rc<TypeBinding>>(),
                                            str_bindings: v1_rt::rc_empty_map::<
                                                String,
                                                Rc<TypeBinding>,
                                            >(
                                            ),
                                            ancestry_str_bindings: v1_rt::rc_empty_map::<
                                                String,
                                                Rc<TypeBinding>,
                                            >(
                                            ),
                                            parents: Rc::new(vec![]),
                                            recursive_types: Rc::new(vec![]),
                                            recursive_type_set: v1_rt::rc_empty_map::<i64, bool>(),
                                            inductive_fields: v1_rt::rc_empty_map::<
                                                String,
                                                Rc<Vec<Rc<InductiveField>>>,
                                            >(
                                            ),
                                            source_indices: source_indices.clone(),
                                            intern_table: empty_intern_table(),
                                        }),
                                    )
                                }
                            }
                        } else {
                            render_rust_applied_type_shared(
                                applied.clone(),
                                Rc::new(vec![]),
                                shared_types.clone(),
                                corpus_repr.clone(),
                                source_indices.clone(),
                                v1_rt::rc_empty_map::<String, String>(),
                                Rc::new(TypeEnv {
                                    bindings: v1_rt::rc_empty_map::<i64, Rc<TypeBinding>>(),
                                    str_bindings: v1_rt::rc_empty_map::<String, Rc<TypeBinding>>(),
                                    ancestry_str_bindings: v1_rt::rc_empty_map::<
                                        String,
                                        Rc<TypeBinding>,
                                    >(),
                                    parents: Rc::new(vec![]),
                                    recursive_types: Rc::new(vec![]),
                                    recursive_type_set: v1_rt::rc_empty_map::<i64, bool>(),
                                    inductive_fields: v1_rt::rc_empty_map::<
                                        String,
                                        Rc<Vec<Rc<InductiveField>>>,
                                    >(),
                                    source_indices: source_indices.clone(),
                                    intern_table: empty_intern_table(),
                                }),
                            )
                        }
                    }
                } else {
                    render_rust_type(
                        n.clone(),
                        shared_types.clone(),
                        corpus_repr.clone(),
                        source_indices.clone(),
                    )
                }
            }
            None => render_rust_type(
                n.clone(),
                shared_types.clone(),
                corpus_repr.clone(),
                source_indices.clone(),
            ),
        }
    }
}

pub fn render_rust_field_type_with_applied_binding(
    field: Rc<Node>,
    generic_param_names: Rc<Vec<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    variant_to_enum: Rc<HashMap<String, String>>,
    env: Rc<TypeEnv>,
) -> String {
    {
        let authored_type = field_node_type_expr(field.clone());
        if ((generic_param_names.clone().len() as i64) > 0) {
            render_rust_decl_type(
                resolved_type(field.clone()),
                generic_param_names.clone(),
                shared_types,
                corpus_repr,
                source_indices.clone(),
                variant_to_enum,
                env,
            )
        } else {
            if (find_property(
                field.properties.clone(),
                "__applied_type_args".to_string(),
                source_indices.clone(),
            ) != None)
            {
                render_rust_type_with_applied_binding(
                    field.clone(),
                    shared_types,
                    corpus_repr,
                    source_indices.clone(),
                )
            } else {
                if (find_property(
                    authored_type.properties.clone(),
                    "__applied_type_args".to_string(),
                    source_indices.clone(),
                ) != None)
                {
                    render_rust_type_with_applied_binding(
                        authored_type.clone(),
                        shared_types,
                        corpus_repr,
                        source_indices.clone(),
                    )
                } else {
                    if ((authored_type.connective.clone() == Connective::NoConnective)
                        && ((authored_type.children.clone().len() as i64) > 0))
                    {
                        render_rust_type(
                            authored_type.clone(),
                            shared_types,
                            corpus_repr,
                            source_indices.clone(),
                        )
                    } else {
                        render_rust_type_with_applied_binding(
                            resolved_type(field.clone()),
                            shared_types,
                            corpus_repr,
                            source_indices.clone(),
                        )
                    }
                }
            }
        }
    }
}

pub fn emit_struct_field_from_child(
    struct_name: String,
    child: Rc<Node>,
    generic_param_names: Rc<Vec<String>>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let rt_child = resolved_type(child.clone());
        let authored_child_type = field_node_type_expr(child.clone());
        let ty = if ((generic_param_names.clone().len() as i64) > 0) {
            render_rust_decl_type(
                rt_child.clone(),
                generic_param_names.clone(),
                shared_types.clone(),
                emit_info.corpus_repr.clone(),
                env.source_indices.clone(),
                emit_info.variant_to_enum.clone(),
                env.clone(),
            )
        } else {
            if (find_property(
                child.properties.clone(),
                "__applied_type_args".to_string(),
                env.source_indices.clone(),
            ) != None)
            {
                render_rust_type_with_applied_binding(
                    child.clone(),
                    shared_types.clone(),
                    emit_info.corpus_repr.clone(),
                    env.source_indices.clone(),
                )
            } else {
                if (find_property(
                    authored_child_type.properties.clone(),
                    "__applied_type_args".to_string(),
                    env.source_indices.clone(),
                ) != None)
                {
                    render_rust_type_with_applied_binding(
                        authored_child_type.clone(),
                        shared_types.clone(),
                        emit_info.corpus_repr.clone(),
                        env.source_indices.clone(),
                    )
                } else {
                    if (find_property(
                        rt_child.properties.clone(),
                        "__applied_type_args".to_string(),
                        env.source_indices.clone(),
                    ) != None)
                    {
                        render_rust_type_with_applied_binding(
                            rt_child.clone(),
                            shared_types.clone(),
                            emit_info.corpus_repr.clone(),
                            env.source_indices.clone(),
                        )
                    } else {
                        if ((is_product_type(rt_child.clone())
                            && (rt_child.ident_span.clone() != None))
                            && ((rt_child.children.clone().len() as i64) > 2))
                        {
                            {
                                let rt_child_name =
                                    authored_name_at(env.source_indices.clone(), rt_child.clone());
                                match lookup_type_by_name(env.clone(), rt_child_name.clone()) {
                                    Some(resolved) => {
                                        if ((resolved.params.clone().len() as i64) > 0) {
                                            {
                                                let base = coerce_primitive_type(
                                                    RenderTarget::Rust,
                                                    rt_child_name.clone(),
                                                );
                                                let param_names = Rc::new({
                                                    let mut __result = Vec::new();
                                                    for p in resolved.params.clone().iter().cloned()
                                                    {
                                                        __result.push(to_pascal(
                                                            generic_param_name_at(
                                                                p.clone(),
                                                                env.source_indices.clone(),
                                                            ),
                                                        ));
                                                    }
                                                    __result
                                                });
                                                let with_params = v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(base, "<".to_string()),
                                                        param_names.join(&", ".to_string()),
                                                    ),
                                                    ">".to_string(),
                                                );
                                                render_rust_shared_type_if_needed(
                                                    rt_child_name.clone(),
                                                    with_params,
                                                    shared_types.clone(),
                                                )
                                            }
                                        } else {
                                            render_rust_type(
                                                rt_child.clone(),
                                                shared_types.clone(),
                                                emit_info.corpus_repr.clone(),
                                                env.source_indices.clone(),
                                            )
                                        }
                                    }
                                    None => render_rust_type(
                                        rt_child.clone(),
                                        shared_types.clone(),
                                        emit_info.corpus_repr.clone(),
                                        env.source_indices.clone(),
                                    ),
                                }
                            }
                        } else {
                            render_rust_type(
                                rt_child.clone(),
                                shared_types.clone(),
                                emit_info.corpus_repr.clone(),
                                env.source_indices.clone(),
                            )
                        }
                    }
                }
            }
        };
        let generic_ty = if (struct_name == "PartialFunction".to_string()) {
            rust_normalize_partial_function_field_type_text(rust_normalize_witness_type_text(ty))
        } else {
            ty
        };
        let final_ty = if needs_box_wrapping(
            rt_child.clone(),
            recursive_types,
            shared_types.clone(),
            env.source_indices.clone(),
        ) {
            v1_rt::concat(
                v1_rt::concat("Box<".to_string(), generic_ty.clone()),
                ">".to_string(),
            )
        } else {
            if (((rt_child.return_cardinality.clone() != Cardinality::CardOptional)
                && v1_rt::set_contains(
                    &shared_types,
                    authored_name_at(env.source_indices.clone(), rt_child.clone()),
                ))
                && !rust_type_is_rc_wrapped(generic_ty.clone()))
            {
                wrap_shared_type(RenderTarget::Rust, generic_ty.clone())
            } else {
                generic_ty.clone()
            }
        };
        let rename_attr = match Rc::new({
            let mut __result = Vec::new();
            for p in child.properties.clone().iter().cloned() {
                if (field_init_node_name_at(p.clone(), env.source_indices.clone())
                    == "from_key".to_string())
                {
                    __result.push(p);
                }
            }
            __result
        })
        .first()
        .cloned()
        {
            Some(prop) => match (*field_init_node_value(prop.clone()).expr_data.clone()).clone() {
                ExprData::ExprLiteral { value: lv, .. } => match (*lv.clone()).clone() {
                    LiteralValue::LitStr { value: key, .. } => v1_rt::concat(
                        v1_rt::concat(
                            "    ".to_string(),
                            apply_type_template1(rust_serde_rename_template_text(), key.clone()),
                        ),
                        "\n".to_string(),
                    ),
                    _ => "".to_string(),
                },
                _ => "".to_string(),
            },
            None => "".to_string(),
        };
        emit_rust_field_definition(
            authored_name(env.clone(), child.clone()),
            final_ty,
            rename_attr,
            "    ".to_string(),
            rust_visibility_prefix(),
        )
    }
}

pub fn emit_rust_field_definition(
    authored: String,
    final_ty: String,
    rename_attr: String,
    indent: String,
    visibility: String,
) -> String {
    {
        let snake = to_snake(authored.clone());
        let emitted = emit_ident(authored.clone(), RenderTarget::Rust);
        let keyword_rename =
            if ((emitted.clone() != snake.clone()) && (rename_attr.clone() == "".to_string())) {
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(indent.clone(), "#[serde(rename = \"".to_string()),
                        snake.clone(),
                    ),
                    "\")]\n".to_string(),
                )
            } else {
                "".to_string()
            };
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(keyword_rename, rename_attr.clone()),
                                indent.clone(),
                            ),
                            visibility,
                        ),
                        emitted.clone(),
                    ),
                    ": ".to_string(),
                ),
                final_ty,
            ),
            ",".to_string(),
        )
    }
}

pub fn enum_derives(name: String, children: Rc<Vec<Rc<Node>>>) -> String {
    {
        let complex = Rc::new({
            let mut __result = Vec::new();
            for v in children.iter().cloned() {
                if ((v.children.clone().len() as i64) > 0) {
                    __result.push(v);
                }
            }
            __result
        });
        match ((complex.len() as i64) == 0) {
            true => rust_ord_derives_copy_text(),
            false => rust_enum_derives_text(),
        }
    }
}

pub fn emit_enum_from_children(
    name: String,
    type_params: String,
    generic_param_names: Rc<Vec<String>>,
    children: Rc<Vec<Rc<Node>>>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    serde_policy: Rc<RustEnumWireSerde>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let derives = enum_derives(name.clone(), children.clone());
        let variant_lines = Rc::new({
            let mut __result = Vec::new();
            for child in children.clone().iter().cloned() {
                __result.push(emit_variant_from_child(
                    child.clone(),
                    name.clone(),
                    generic_param_names.clone(),
                    recursive_types.clone(),
                    shared_types.clone(),
                    env.clone(),
                    serde_policy.clone(),
                    emit_info.clone(),
                ));
            }
            __result
        });
        let variants_str = variant_lines.join(&"\n".to_string());
        let tag_line = if (serde_policy.enum_attr.clone() == "".to_string()) {
            "".to_string()
        } else {
            v1_rt::concat(serde_policy.enum_attr.clone(), "\n".to_string())
        };
        let enum_def = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(derives, "\n".to_string()),
                                            tag_line,
                                        ),
                                        rust_visibility_prefix(),
                                    ),
                                    rust_items().enum_keyword.clone(),
                                ),
                                " ".to_string(),
                            ),
                            name.clone(),
                        ),
                        type_params.clone(),
                    ),
                    " {\n".to_string(),
                ),
                variants_str,
            ),
            "\n}".to_string(),
        );
        let accessor_impl = emit_enum_shared_accessors(
            name.clone(),
            type_params.clone(),
            generic_param_names.clone(),
            children.clone(),
            recursive_types.clone(),
            shared_types.clone(),
            env.clone(),
            emit_info.clone(),
        );
        if (accessor_impl.clone() == "".to_string()) {
            enum_def
        } else {
            v1_rt::concat(
                v1_rt::concat(enum_def, "\n".to_string()),
                accessor_impl.clone(),
            )
        }
    }
}

pub fn find_shared_enum_fields(children: Rc<Vec<Rc<Node>>>, env: Rc<TypeEnv>) -> Rc<Vec<String>> {
    {
        let fielded = Rc::new({
            let mut __result = Vec::new();
            for child in children.iter().cloned() {
                if (((child.children.clone().len() as i64) > 0)
                    && !variant_is_synthetic_positional_payload(
                        child.children.clone(),
                        env.source_indices.clone(),
                    ))
                {
                    __result.push(child);
                }
            }
            __result
        });
        if ((fielded.clone().len() as i64) == 0) {
            return Rc::new(vec![]);
        }
        let first_fields = match fielded.clone().first().cloned() {
            Some(v) => Rc::new({
                let mut __result = Vec::new();
                for f in v.children.clone().iter().cloned() {
                    __result.push(authored_name(env.clone(), f.clone()));
                }
                __result
            }),
            None => Rc::new(vec![]),
        };
        Rc::new({
            let mut __result = Vec::new();
            for fname in first_fields.iter().cloned() {
                if {
                    let mut __all = true;
                    for variant in fielded.clone().iter().cloned() {
                        if !({
                            let mut __found = false;
                            for f in variant.children.clone().iter().cloned() {
                                if (authored_name(env.clone(), f.clone()) == fname.clone()) {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        }) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                } {
                    __result.push(fname);
                }
            }
            __result
        })
    }
}

pub fn emit_enum_shared_accessors(
    name: String,
    type_params: String,
    generic_param_names: Rc<Vec<String>>,
    children: Rc<Vec<Rc<Node>>>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let all_shared = find_shared_enum_fields(children.clone(), env.clone());
        if ((all_shared.clone().len() as i64) == 0) {
            return "".to_string();
        }
        let fielded = Rc::new({
            let mut __result = Vec::new();
            for child in children.clone().iter().cloned() {
                if (((child.children.clone().len() as i64) > 0)
                    && !variant_is_synthetic_positional_payload(
                        child.children.clone(),
                        env.source_indices.clone(),
                    ))
                {
                    __result.push(child);
                }
            }
            __result
        });
        if ((fielded.clone().len() as i64) == 0) {
            return "compile_error!(\"enum shared accessor missing fielded variant\")".to_string();
        }
        let first_fielded = fielded.clone().first().cloned().clone().unwrap();
        let shared = Rc::new({
            let mut __result = Vec::new();
            for fname in all_shared.clone().iter().cloned() {
                if {
                    let types = Rc::new({
                        let mut __result = Vec::new();
                        for variant in fielded.clone().iter().cloned() {
                            __result.push(
                                match Rc::new({
                                    let mut __result = Vec::new();
                                    for f in variant.children.clone().iter().cloned() {
                                        if (authored_name(env.clone(), f.clone()) == fname.clone())
                                        {
                                            __result.push(f);
                                        }
                                    }
                                    __result
                                })
                                .first()
                                .cloned()
                                {
                                    Some(f) => render_rust_field_type_with_applied_binding(
                                        f.clone(),
                                        generic_param_names.clone(),
                                        shared_types.clone(),
                                        emit_info.corpus_repr.clone(),
                                        env.source_indices.clone(),
                                        emit_info.variant_to_enum.clone(),
                                        env.clone(),
                                    ),
                                    None => "".to_string(),
                                },
                            );
                        }
                        __result
                    });
                    let first_type = match types.clone().first().cloned() {
                        Some(t) => t.clone(),
                        None => "".to_string(),
                    };
                    {
                        let mut __all = true;
                        for t in types.clone().iter().cloned() {
                            if !(t.clone() == first_type.clone()) {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    }
                } {
                    __result.push(fname);
                }
            }
            __result
        });
        if ((shared.clone().len() as i64) == 0) {
            return "".to_string();
        }
        let accessor_fns = Rc::new({
            let mut __result = Vec::new();
            for fname in shared.clone().iter().cloned() {
                __result.push({
                    let ty = match Rc::new({
                        let mut __result = Vec::new();
                        for f in first_fielded.children.clone().iter().cloned() {
                            if (authored_name(env.clone(), f.clone()) == fname.clone()) {
                                __result.push(f);
                            }
                        }
                        __result
                    })
                    .first()
                    .cloned()
                    {
                        Some(f) => render_rust_field_type_with_applied_binding(
                            f.clone(),
                            generic_param_names.clone(),
                            shared_types.clone(),
                            emit_info.corpus_repr.clone(),
                            env.source_indices.clone(),
                            emit_info.variant_to_enum.clone(),
                            env.clone(),
                        ),
                        None => "compile_error!(\"enum shared accessor missing field metadata\")"
                            .to_string(),
                    };
                    let arms = Rc::new({
                        let mut __result = Vec::new();
                        for child in children.clone().iter().cloned() {
                            __result.push({
                                let child_text = authored_name(env.clone(), child.clone());
                                let sharing = language_spec(RenderTarget::Rust).sharing.clone();
                                if ((child.children.clone().len() as i64) == 0) {
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            "            ".to_string(),
                                                            name.clone(),
                                                        ),
                                                        "::".to_string(),
                                                    ),
                                                    child_text.clone(),
                                                ),
                                                " => panic!(\"no ".to_string(),
                                            ),
                                            fname.clone(),
                                        ),
                                        " on unit variant\"),".to_string(),
                                    )
                                } else {
                                    if variant_is_synthetic_positional_payload(
                                        child.children.clone(),
                                        env.source_indices.clone(),
                                    ) {
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                "            ".to_string(),
                                                                name.clone(),
                                                            ),
                                                            "::".to_string(),
                                                        ),
                                                        child_text.clone(),
                                                    ),
                                                    "(_) => panic!(\"no ".to_string(),
                                                ),
                                                fname.clone(),
                                            ),
                                            " on positional-payload variant\"),".to_string(),
                                        )
                                    } else {
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                v1_rt::concat(
                                                                    v1_rt::concat(
                                                                        "            ".to_string(),
                                                                        name.clone(),
                                                                    ),
                                                                    "::".to_string(),
                                                                ),
                                                                child_text.clone(),
                                                            ),
                                                            " { ".to_string(),
                                                        ),
                                                        emit_ident(
                                                            fname.clone(),
                                                            RenderTarget::Rust,
                                                        ),
                                                    ),
                                                    ": __val, .. } => ".to_string(),
                                                ),
                                                apply_type_template1(
                                                    sharing.clone_value.clone(),
                                                    "__val".to_string(),
                                                ),
                                            ),
                                            ",".to_string(),
                                        )
                                    }
                                }
                            });
                        }
                        __result
                    });
                    let arms_str = arms.clone().join(&"\n".to_string());
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            "    pub fn ".to_string(),
                                            emit_ident(fname.clone(), RenderTarget::Rust),
                                        ),
                                        "(&self) -> ".to_string(),
                                    ),
                                    ty.clone(),
                                ),
                                " {\n        match self {\n".to_string(),
                            ),
                            arms_str.clone(),
                        ),
                        "\n        }\n    }".to_string(),
                    )
                });
            }
            __result
        });
        let fns_str = accessor_fns.join(&"\n".to_string());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat("impl".to_string(), type_params.clone()),
                                " ".to_string(),
                            ),
                            name.clone(),
                        ),
                        type_params.clone(),
                    ),
                    " {\n".to_string(),
                ),
                fns_str,
            ),
            "\n}".to_string(),
        )
    }
}

pub fn string_without_prefix(value: String, prefix: String) -> Option<String> {
    if (v1_rt::string_length(&prefix) == 0) {
        None
    } else {
        if ((v1_rt::string_length(&value) >= v1_rt::string_length(&prefix))
            && (v1_rt::substring(&value, 0, v1_rt::string_length(&prefix)) == prefix.clone()))
        {
            Some(v1_rt::substring(
                &value,
                v1_rt::string_length(&prefix),
                v1_rt::string_length(&value),
            ))
        } else {
            None
        }
    }
}

pub fn string_without_suffix(value: String, suffix: String) -> Option<String> {
    if (v1_rt::string_length(&suffix) == 0) {
        None
    } else {
        if ((v1_rt::string_length(&value) >= v1_rt::string_length(&suffix))
            && (v1_rt::substring(
                &value,
                (v1_rt::string_length(&value) - v1_rt::string_length(&suffix)),
                v1_rt::string_length(&value),
            ) == suffix.clone()))
        {
            Some(v1_rt::substring(
                &value,
                0,
                (v1_rt::string_length(&value) - v1_rt::string_length(&suffix)),
            ))
        } else {
            None
        }
    }
}

pub fn string_index_of_from(mut haystack: String, mut needle: String, mut pos: i64) -> Option<i64> {
    loop {
        if ((pos.clone() + v1_rt::string_length(&needle)) > v1_rt::string_length(&haystack)) {
            break None;
        } else {
            if (v1_rt::substring(
                &haystack,
                pos.clone(),
                (pos.clone() + v1_rt::string_length(&needle)),
            ) == needle.clone())
            {
                break Some(pos.clone());
            } else {
                {
                    let __tco_0 = (pos + 1);
                    pos = __tco_0;
                    continue;
                }
            }
        }
    }
}

pub fn string_index_of(haystack: String, needle: String) -> Option<i64> {
    string_index_of_from(haystack, needle, 0)
}

pub fn wire_variant_tag_for_policy(
    authored: String,
    policy: Rc<RustEnumWireSerde>,
) -> Option<String> {
    if (policy.error_message.clone() != None) {
        None
    } else {
        match policy.rename_style.clone() {
            Some(style) => {
                if (style.clone() == "StripAffixAndSnakeCase".to_string()) {
                    {
                        let without_prefix = match policy.rename_prefix.clone() {
                            Some(prefix) => match string_without_prefix(authored, prefix.clone()) {
                                Some(stripped) => stripped.clone(),
                                None => return None,
                            },
                            None => authored,
                        };
                        let without_suffix = match policy.rename_suffix.clone() {
                            Some(suffix) => {
                                match string_without_suffix(without_prefix, suffix.clone()) {
                                    Some(stripped) => stripped.clone(),
                                    None => return None,
                                }
                            }
                            None => without_prefix,
                        };
                        Some(to_snake(without_suffix))
                    }
                } else {
                    None
                }
            }
            None => {
                if v1_rt::contains(
                    policy.enum_attr.clone(),
                    "rename_all = \"snake_case\"".to_string(),
                ) {
                    Some(to_snake(authored))
                } else {
                    if (((policy.enum_attr.clone() == "".to_string())
                        && (policy.rename_prefix.clone() == None))
                        && (policy.rename_suffix.clone() == None))
                    {
                        Some(authored)
                    } else {
                        None
                    }
                }
            }
        }
    }
}

pub fn policy_serde_tag_field(policy: Rc<RustEnumWireSerde>) -> Option<String> {
    {
        let needle = "tag = \"".to_string();
        match string_index_of(policy.enum_attr.clone(), needle.clone()) {
            Some(start) => {
                let after = (start.clone() + v1_rt::string_length(&needle));
                match string_index_of_from(
                    policy.enum_attr.clone(),
                    "\"".to_string(),
                    after.clone(),
                ) {
                    Some(end) => Some(v1_rt::substring(
                        &policy.enum_attr.clone(),
                        after.clone(),
                        end.clone(),
                    )),
                    None => None,
                }
            }
            None => None,
        }
    }
}

pub fn policy_is_untagged(policy: Rc<RustEnumWireSerde>) -> bool {
    v1_rt::contains(policy.enum_attr.clone(), "untagged".to_string())
}

pub fn policy_is_string_variant(policy: Rc<RustEnumWireSerde>) -> bool {
    (((!v1_rt::contains(policy.enum_attr.clone(), "tag =".to_string())
        && (policy.rename_prefix.clone() == None))
        && (policy.rename_suffix.clone() == None))
        && (policy.rename_style.clone() == None))
}

pub fn wire_variant_rename_attr_for_policy(
    authored: String,
    policy: Rc<RustEnumWireSerde>,
) -> String {
    match wire_variant_tag_for_policy(authored, policy.clone()) {
        Some(tag) => match policy.rename_style.clone() {
            Some(style) => {
                if (style.clone() == "StripAffixAndSnakeCase".to_string()) {
                    v1_rt::concat(
                        v1_rt::concat("    #[serde(rename = \"".to_string(), tag.clone()),
                        "\")]\n".to_string(),
                    )
                } else {
                    "".to_string()
                }
            }
            None => "".to_string(),
        },
        None => "".to_string(),
    }
}

pub fn variant_rename_validation_for_policy(
    authored: String,
    policy: Rc<RustEnumWireSerde>,
) -> String {
    match policy.rename_style.clone() {
        Some(style) => {
            if (style.clone() == "StripAffixAndSnakeCase".to_string()) {
                {
                    let without_prefix = match policy.rename_prefix.clone() {
                        Some(prefix) => {
                            match string_without_prefix(authored.clone(), prefix.clone()) {
                                Some(stripped) => stripped.clone(),
                                None => {
                                    return emit_rust_compile_error_item(v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat("variant ".to_string(), authored.clone()),
                                            " does not satisfy declared wire rename prefix: "
                                                .to_string(),
                                        ),
                                        prefix.clone(),
                                    ))
                                }
                            }
                        }
                        None => authored.clone(),
                    };
                    match policy.rename_suffix.clone() {
                        Some(suffix) => match string_without_suffix(without_prefix, suffix.clone())
                        {
                            Some(_) => "".to_string(),
                            None => emit_rust_compile_error_item(v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat("variant ".to_string(), authored.clone()),
                                    " does not satisfy declared wire rename suffix: ".to_string(),
                                ),
                                suffix.clone(),
                            )),
                        },
                        None => "".to_string(),
                    }
                }
            } else {
                "".to_string()
            }
        }
        None => "".to_string(),
    }
}

pub fn variant_rename_validations_for_policy(
    children: Rc<Vec<Rc<Node>>>,
    env: Rc<TypeEnv>,
    serde_policy: Rc<RustEnumWireSerde>,
) -> String {
    Rc::new({
        let mut __result = Vec::new();
        for text in Rc::new({
            let mut __result = Vec::new();
            for child in children.iter().cloned() {
                __result.push(variant_rename_validation_for_policy(
                    authored_name(env.clone(), child.clone()),
                    serde_policy.clone(),
                ));
            }
            __result
        })
        .iter()
        .cloned()
        {
            if (text.clone() != "".to_string()) {
                __result.push(text);
            }
        }
        __result
    })
    .join(&"\n".to_string())
}

pub fn enum_variant_field_type_node(
    env: Rc<TypeEnv>,
    enum_name: String,
    variant_name: String,
    field_name: String,
    fallback: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Node> {
    match lookup_type_by_name(env, enum_name) {
        Some(enum_node) => {
            match find_child_named(enum_node.clone(), variant_name, source_indices.clone()) {
                Some(variant) => {
                    match find_child_named(variant.clone(), field_name, source_indices.clone()) {
                        Some(field) => {
                            if (field.inferred.clone() != None) {
                                resolved_type(field.clone())
                            } else {
                                fallback
                            }
                        }
                        None => fallback,
                    }
                }
                None => fallback,
            }
        }
        None => fallback,
    }
}

pub fn render_variant_payload_type(
    n: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    if ((n.connective.clone() == Connective::NoConnective)
        && ((n.children.clone().len() as i64) > 0))
    {
        {
            let tn = authored_name_at(source_indices.clone(), n.clone());
            let args = Rc::new({
                let mut __result = Vec::new();
                for c in n.children.clone().iter().cloned() {
                    __result.push(render_rust_type(
                        child_type_node(c.clone()),
                        shared_types.clone(),
                        corpus_repr.clone(),
                        source_indices.clone(),
                    ));
                }
                __result
            });
            let spec = language_spec(RenderTarget::Rust);
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        coerce_primitive_type(RenderTarget::Rust, tn),
                        spec.type_arg_open.clone(),
                    ),
                    args.join(&", ".to_string()),
                ),
                spec.type_arg_close.clone(),
            )
        }
    } else {
        render_rust_type(
            n.clone(),
            shared_types.clone(),
            corpus_repr.clone(),
            source_indices.clone(),
        )
    }
}

pub fn variant_is_synthetic_positional_payload(
    fields: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    if ((fields.clone().len() as i64) != 1) {
        false
    } else {
        match fields.clone().first().cloned() {
            Some(f) => (field_node_name_at(f.clone(), source_indices) == "0".to_string()),
            None => false,
        }
    }
}

pub fn emit_variant_from_child(
    child: Rc<Node>,
    enum_name: String,
    generic_param_names: Rc<Vec<String>>,
    recursive_types: Rc<std::collections::BTreeSet<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    env: Rc<TypeEnv>,
    serde_policy: Rc<RustEnumWireSerde>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let child_text = authored_name(env.clone(), child.clone());
        let rename_attr =
            wire_variant_rename_attr_for_policy(child_text.clone(), serde_policy.clone());
        if ((child.children.clone().len() as i64) == 0) {
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(rename_attr, "    ".to_string()),
                    child_text.clone(),
                ),
                ",".to_string(),
            )
        } else {
            if ((child.children.clone().len() as i64) == 1) {
                {
                    let positional_payload = variant_is_synthetic_positional_payload(
                        child.children.clone(),
                        env.source_indices.clone(),
                    );
                    let tuple_style = (positional_payload.clone()
                        || (serde_policy.enum_attr.clone() == "#[serde(untagged)]".to_string()));
                    if tuple_style {
                        match child.children.clone().first().cloned() {
                            Some(f) => {
                                let fallback = resolved_type(f.clone());
                                let type_node = if positional_payload.clone() {
                                    enum_variant_field_type_node(
                                        env.clone(),
                                        enum_name,
                                        child_text.clone(),
                                        "0".to_string(),
                                        fallback,
                                        env.source_indices.clone(),
                                    )
                                } else {
                                    fallback
                                };
                                let raw_ty = if positional_payload.clone() {
                                    render_variant_payload_type(
                                        type_node.clone(),
                                        shared_types.clone(),
                                        emit_info.corpus_repr.clone(),
                                        env.source_indices.clone(),
                                    )
                                } else {
                                    render_rust_type(
                                        type_node.clone(),
                                        shared_types.clone(),
                                        emit_info.corpus_repr.clone(),
                                        env.source_indices.clone(),
                                    )
                                };
                                let ty = if (find_property(
                                    type_node.properties.clone(),
                                    "__applied_type_args".to_string(),
                                    env.source_indices.clone(),
                                ) != None)
                                {
                                    render_rust_type_with_applied_binding(
                                        type_node.clone(),
                                        shared_types.clone(),
                                        emit_info.corpus_repr.clone(),
                                        env.source_indices.clone(),
                                    )
                                } else {
                                    raw_ty
                                };
                                let final_ty = if needs_box_wrapping(
                                    type_node.clone(),
                                    recursive_types.clone(),
                                    shared_types.clone(),
                                    env.source_indices.clone(),
                                ) {
                                    v1_rt::concat(
                                        v1_rt::concat("Box<".to_string(), ty.clone()),
                                        ">".to_string(),
                                    )
                                } else {
                                    ty.clone()
                                };
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(rename_attr, "    ".to_string()),
                                                child_text.clone(),
                                            ),
                                            "(".to_string(),
                                        ),
                                        final_ty.clone(),
                                    ),
                                    "),".to_string(),
                                )
                            }
                            None => v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(rename_attr, "    ".to_string()),
                                    child_text.clone(),
                                ),
                                ",".to_string(),
                            ),
                        }
                    } else {
                        {
                            let field_lines = Rc::new({
                                let mut __result = Vec::new();
                                for f in child.children.clone().iter().cloned() {
                                    __result.push({
                                        let rt_f = resolved_type(f.clone());
                                        let ty = render_rust_field_type_with_applied_binding(
                                            f.clone(),
                                            generic_param_names.clone(),
                                            shared_types.clone(),
                                            emit_info.corpus_repr.clone(),
                                            env.source_indices.clone(),
                                            emit_info.variant_to_enum.clone(),
                                            env.clone(),
                                        );
                                        let final_ty = if needs_box_wrapping(
                                            rt_f.clone(),
                                            recursive_types.clone(),
                                            shared_types.clone(),
                                            env.source_indices.clone(),
                                        ) {
                                            v1_rt::concat(
                                                v1_rt::concat("Box<".to_string(), ty.clone()),
                                                ">".to_string(),
                                            )
                                        } else {
                                            ty.clone()
                                        };
                                        emit_rust_field_definition(
                                            authored_name(env.clone(), f.clone()),
                                            final_ty.clone(),
                                            "".to_string(),
                                            "        ".to_string(),
                                            "".to_string(),
                                        )
                                    });
                                }
                                __result
                            });
                            let fields_str = field_lines.join(&"\n".to_string());
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(rename_attr, "    ".to_string()),
                                            child_text.clone(),
                                        ),
                                        " {\n".to_string(),
                                    ),
                                    fields_str,
                                ),
                                "\n    },".to_string(),
                            )
                        }
                    }
                }
            } else {
                {
                    let field_lines = Rc::new({
                        let mut __result = Vec::new();
                        for f in child.children.clone().iter().cloned() {
                            __result.push({
                                let rt_f = resolved_type(f.clone());
                                let ty = render_rust_field_type_with_applied_binding(
                                    f.clone(),
                                    generic_param_names.clone(),
                                    shared_types.clone(),
                                    emit_info.corpus_repr.clone(),
                                    env.source_indices.clone(),
                                    emit_info.variant_to_enum.clone(),
                                    env.clone(),
                                );
                                let final_ty = if needs_box_wrapping(
                                    rt_f.clone(),
                                    recursive_types.clone(),
                                    shared_types.clone(),
                                    env.source_indices.clone(),
                                ) {
                                    v1_rt::concat(
                                        v1_rt::concat("Box<".to_string(), ty.clone()),
                                        ">".to_string(),
                                    )
                                } else {
                                    ty.clone()
                                };
                                emit_rust_field_definition(
                                    authored_name(env.clone(), f.clone()),
                                    final_ty.clone(),
                                    "".to_string(),
                                    "        ".to_string(),
                                    "".to_string(),
                                )
                            });
                        }
                        __result
                    });
                    let fields_str = field_lines.join(&"\n".to_string());
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(rename_attr, "    ".to_string()),
                                    child_text.clone(),
                                ),
                                " {\n".to_string(),
                            ),
                            fields_str,
                        ),
                        "\n    },".to_string(),
                    )
                }
            }
        }
    }
}

pub fn emit_fn_def(
    name: String,
    params: Rc<Vec<Rc<Node>>>,
    inferred: Rc<Node>,
    body: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let si = (*scope.type_env).clone().source_indices.clone();
        let host_text_op = if corpus_repr_is_host(emit_info.corpus_repr.clone()) {
            rust_host_string_op_fn_emit(name.clone())
        } else {
            None
        };
        if (host_text_op.clone() != None) {
            return match host_text_op.clone() {
                Some(op_fn) => op_fn.clone(),
                None => "".to_string(),
            };
        }
        match rust_host_string_seam_fn_emit(name.clone()) {
            Some(seam_fn) => {
                if corpus_repr_is_faithful(emit_info.corpus_repr.clone()) {
                    seam_fn.clone()
                } else {
                    "".to_string()
                }
            }
            None => {
                let type_params = function_type_params(params.clone());
                let value_params = function_value_params(params.clone());
                if function_type_params_have_collision(type_params.clone()) {
                    return v1_rt::concat(v1_rt::concat("compile_error!(\"type param name collides with a value param in fn '".to_string(), name.clone()), "' — a value param shares its name with a declared type param; rename the value param or dissolve via ParamKind/params-slot partition\");\n".to_string());
                }
                let generic_param_names = Rc::new({
                    let mut __result = Vec::new();
                    for p in type_params.clone().iter().cloned() {
                        __result.push(generic_param_name_at(p.clone(), si.clone()));
                    }
                    __result
                });
                let value_param_names = Rc::new({
                    let mut __result = Vec::new();
                    for p in value_params.clone().iter().cloned() {
                        __result.push(p.name.clone());
                    }
                    __result
                });
                let ret_name = authored_name_at(si.clone(), inferred.clone());
                let return_is_bare_generic = ((Rc::new({
                    let mut __result = Vec::new();
                    for g in generic_param_names.clone().iter().cloned() {
                        if (g.clone() == ret_name.clone()) {
                            __result.push(g);
                        }
                    }
                    __result
                })
                .len() as i64)
                    > 0);
                let body_is_param_ref = ((Rc::new({
                    let mut __result = Vec::new();
                    for n in value_param_names.iter().cloned() {
                        if (n.clone() == body.name.clone()) {
                            __result.push(n);
                        }
                    }
                    __result
                })
                .len() as i64)
                    > 0);
                let needs_clone_bound = (return_is_bare_generic && !body_is_param_ref);
                let type_params_str = if needs_clone_bound {
                    emit_type_params_with_clone_bound(
                        type_params.clone(),
                        ret_name.clone(),
                        si.clone(),
                    )
                } else {
                    emit_type_params(type_params.clone(), si.clone())
                };
                let params_str = emit_params(
                    value_params.clone(),
                    generic_param_names.clone(),
                    shared_types.clone(),
                    emit_info.corpus_repr.clone(),
                    si.clone(),
                    emit_info.read_only_params.clone(),
                    emit_info.variant_to_enum.clone(),
                    scope.type_env.clone(),
                );
                let ret_str = emit_inferred(
                    inferred.clone(),
                    generic_param_names.clone(),
                    shared_types.clone(),
                    emit_info.corpus_repr.clone(),
                    si.clone(),
                    emit_info.variant_to_enum.clone(),
                    scope.type_env.clone(),
                );
                let body_scope = build_params_scope(scope.clone(), value_params.clone());
                let depth = 0;
                let use_tco =
                    is_tco_eligible(name.clone(), body.clone(), registry.clone(), si.clone());
                let needs_stacker =
                    (is_self_recursive(name.clone(), body.clone(), registry.clone(), si.clone())
                        && (use_tco.clone() == false));
                if use_tco.clone() {
                    {
                        let tco_params_str = emit_tco_params(
                            value_params.clone(),
                            generic_param_names.clone(),
                            shared_types.clone(),
                            emit_info.corpus_repr.clone(),
                            si.clone(),
                            emit_info.variant_to_enum.clone(),
                            scope.type_env.clone(),
                        );
                        let body_str = emit_typed_tco_body(
                            body.clone(),
                            name.clone(),
                            value_params.clone(),
                            registry.clone(),
                            body_scope,
                            (depth.clone() + 1),
                            shared_types.clone(),
                            emit_info.clone(),
                        );
                        let kw = rust_items().func_keyword.clone();
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                v1_rt::concat(
                                                                    v1_rt::concat(
                                                                        rust_visibility_prefix(),
                                                                        kw,
                                                                    ),
                                                                    " ".to_string(),
                                                                ),
                                                                emit_ident(
                                                                    name.clone(),
                                                                    RenderTarget::Rust,
                                                                ),
                                                            ),
                                                            type_params_str,
                                                        ),
                                                        "(".to_string(),
                                                    ),
                                                    tco_params_str,
                                                ),
                                                ")".to_string(),
                                            ),
                                            ret_str,
                                        ),
                                        " {\n".to_string(),
                                    ),
                                    make_indent((depth.clone() + 1)),
                                ),
                                body_str,
                            ),
                            "\n}".to_string(),
                        )
                    }
                } else {
                    emit_fn_def_non_tco(
                        name.clone(),
                        type_params_str,
                        params_str,
                        ret_str,
                        body.clone(),
                        registry.clone(),
                        body_scope,
                        depth.clone(),
                        shared_types.clone(),
                        emit_info.clone(),
                        needs_stacker,
                    )
                }
            }
        }
    }
}

pub fn emit_fn_def_non_tco(
    name: String,
    type_params_str: String,
    params_str: String,
    ret_str: String,
    body: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
    needs_stacker: bool,
) -> String {
    if needs_stacker {
        {
            let body_str = emit_typed_expr(
                body,
                registry,
                scope,
                (depth.clone() + 2),
                shared_types,
                emit_info,
                1024,
            );
            let kw = rust_items().func_keyword.clone();
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(
                                                            v1_rt::concat(
                                                                v1_rt::concat(
                                                                    v1_rt::concat(
                                                                        v1_rt::concat(
                                                                            rust_visibility_prefix(
                                                                            ),
                                                                            kw,
                                                                        ),
                                                                        " ".to_string(),
                                                                    ),
                                                                    emit_ident(
                                                                        name,
                                                                        RenderTarget::Rust,
                                                                    ),
                                                                ),
                                                                type_params_str,
                                                            ),
                                                            "(".to_string(),
                                                        ),
                                                        params_str,
                                                    ),
                                                    ")".to_string(),
                                                ),
                                                ret_str,
                                            ),
                                            " {\n".to_string(),
                                        ),
                                        make_indent((depth.clone() + 1)),
                                    ),
                                    "stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {\n"
                                        .to_string(),
                                ),
                                make_indent((depth.clone() + 2)),
                            ),
                            body_str,
                        ),
                        "\n".to_string(),
                    ),
                    make_indent((depth.clone() + 1)),
                ),
                "})\n}".to_string(),
            )
        }
    } else {
        {
            let body_str = emit_typed_expr(
                body,
                registry,
                scope,
                (depth.clone() + 1),
                shared_types,
                emit_info,
                1024,
            );
            let kw = rust_items().func_keyword.clone();
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        v1_rt::concat(rust_visibility_prefix(), kw),
                                                        " ".to_string(),
                                                    ),
                                                    emit_ident(name, RenderTarget::Rust),
                                                ),
                                                type_params_str,
                                            ),
                                            "(".to_string(),
                                        ),
                                        params_str,
                                    ),
                                    ")".to_string(),
                                ),
                                ret_str,
                            ),
                            " {\n".to_string(),
                        ),
                        make_indent((depth.clone() + 1)),
                    ),
                    body_str,
                ),
                "\n}".to_string(),
            )
        }
    }
}

pub fn emit_func_def(
    name: String,
    params: Rc<Vec<Rc<Node>>>,
    inferred: Rc<Node>,
    uses: Rc<Vec<Rc<Node>>>,
    body: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        if ((function_type_params(params.clone()).len() as i64) > 0) {
            return v1_rt::concat(v1_rt::concat("compile_error!(\"emit_func_def saw type params in `".to_string(), name.clone()), "` — func/pattern/interface don't route through the generic-fn split today; the parser invariant at parse_block_body_from_prefix has changed. Plumb type_params through this path or dissolve via ParamKind/params-slot partition.\");\n".to_string());
        }
        let depth = 0;
        let service_names = match lookup_item(registry.clone(), name.clone()) {
            Some(info) => info.service_names.clone(),
            None => Rc::new(vec![]),
        };
        let params_str = emit_func_params(
            params.clone(),
            uses.clone(),
            service_names,
            shared_types.clone(),
            emit_info.corpus_repr.clone(),
            (*scope.type_env).clone().source_indices.clone(),
            emit_info.read_only_params.clone(),
            emit_info.variant_to_enum.clone(),
            scope.type_env.clone(),
        );
        let ret_str = emit_func_inferred(
            inferred,
            shared_types.clone(),
            emit_info.corpus_repr.clone(),
            (*scope.type_env).clone().source_indices.clone(),
        );
        let body_scope = build_params_scope(scope.clone(), params.clone());
        let si = (*scope.type_env).clone().source_indices.clone();
        let body_scope = uses.clone().iter().cloned().fold(
            body_scope.clone(),
            |s: Rc<InferScope>, u: Rc<Node>| {
                extend_scope(
                    s,
                    resource_use_name_at(u.clone(), si.clone()),
                    resource_use_resource(u.clone()),
                    Rc::new(SubValueRelation::SubValueUnknown),
                )
            },
        );
        let body_str = emit_func_body(
            body,
            registry.clone(),
            body_scope.clone(),
            (depth.clone() + 1),
            shared_types.clone(),
            emit_info.clone(),
        );
        let items = rust_items();
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        rust_visibility_prefix(),
                                                        items.async_prefix.clone(),
                                                    ),
                                                    items.func_keyword.clone(),
                                                ),
                                                " ".to_string(),
                                            ),
                                            emit_ident(name.clone(), RenderTarget::Rust),
                                        ),
                                        "(".to_string(),
                                    ),
                                    params_str,
                                ),
                                ")".to_string(),
                            ),
                            ret_str,
                        ),
                        " {\n".to_string(),
                    ),
                    make_indent((depth.clone() + 1)),
                ),
                body_str,
            ),
            "\n}".to_string(),
        )
    }
}

pub fn emit_func_body(
    body: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let si = (*scope.type_env).clone().source_indices.clone();
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprLet => {
                let n = let_binding_name_at(body.clone(), si);
                let v = let_value(body.clone());
                let inner = let_body(body.clone());
                let val_str = emit_typed_expr(
                    v.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    shared_types.clone(),
                    emit_info.clone(),
                    1024,
                );
                let let_line = emit_let_binding(n.clone(), val_str, RenderTarget::Rust);
                let next_scope = extend_scope(
                    scope.clone(),
                    n.clone(),
                    resolved_type(v.clone()),
                    Rc::new(SubValueRelation::SubValueUnknown),
                );
                match inner {
                    Some(bd) => v1_rt::concat(
                        v1_rt::concat(let_line, "\n".to_string()),
                        emit_func_body(
                            bd.clone(),
                            registry.clone(),
                            next_scope,
                            depth.clone(),
                            shared_types.clone(),
                            emit_info.clone(),
                        ),
                    ),
                    None => let_line,
                }
            }
            ExprData::ExprBlock => {
                let ss = body.children.clone();
                if ((ss.clone().len() as i64) == 0) {
                    "Ok(())".to_string()
                } else {
                    {
                        let init_state = emit_rust_init_block_stmts(
                            ss.clone(),
                            Rc::new(vec![]),
                            scope.clone(),
                            registry.clone(),
                            depth.clone(),
                            shared_types.clone(),
                            emit_info.clone(),
                        );
                        let last_stmt = ss.clone().last().cloned();
                        let last_str = match last_stmt {
                            Some(s) => match (*s.expr_data.clone()).clone() {
                                ExprData::ExprReturn => v1_rt::concat(
                                    v1_rt::concat(
                                        "return Ok(".to_string(),
                                        emit_typed_expr(
                                            return_value(s.clone()),
                                            registry.clone(),
                                            init_state.scope.clone(),
                                            depth.clone(),
                                            shared_types.clone(),
                                            emit_info.clone(),
                                            1024,
                                        ),
                                    ),
                                    ")".to_string(),
                                ),
                                _ => v1_rt::concat(
                                    v1_rt::concat(
                                        "Ok(".to_string(),
                                        emit_typed_expr(
                                            s.clone(),
                                            registry.clone(),
                                            init_state.scope.clone(),
                                            depth.clone(),
                                            shared_types.clone(),
                                            emit_info.clone(),
                                            1024,
                                        ),
                                    ),
                                    ")".to_string(),
                                ),
                            },
                            None => "Ok(())".to_string(),
                        };
                        if ((init_state.text.clone().len() as i64) == 0) {
                            last_str
                        } else {
                            v1_rt::concat(
                                v1_rt::concat(
                                    init_state.text.clone().join(&"\n".to_string()),
                                    "\n".to_string(),
                                ),
                                last_str,
                            )
                        }
                    }
                }
            }
            ExprData::ExprReturn => v1_rt::concat(
                v1_rt::concat(
                    "return Ok(".to_string(),
                    emit_typed_expr(
                        return_value(body.clone()),
                        registry.clone(),
                        scope.clone(),
                        depth.clone(),
                        shared_types.clone(),
                        emit_info.clone(),
                        1024,
                    ),
                ),
                ")".to_string(),
            ),
            _ => v1_rt::concat(
                v1_rt::concat(
                    "Ok(".to_string(),
                    emit_typed_expr(
                        body.clone(),
                        registry.clone(),
                        scope.clone(),
                        depth.clone(),
                        shared_types.clone(),
                        emit_info.clone(),
                        1024,
                    ),
                ),
                ")".to_string(),
            ),
        }
    })
}

pub fn emit_tco_params(
    params: Rc<Vec<Rc<Node>>>,
    generic_param_names: Rc<Vec<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    variant_to_enum: Rc<HashMap<String, String>>,
    env: Rc<TypeEnv>,
) -> String {
    {
        let strs = Rc::new({
            let mut __result = Vec::new();
            for p in params.iter().cloned() {
                __result.push(emit_tco_param(
                    p.clone(),
                    generic_param_names.clone(),
                    shared_types.clone(),
                    corpus_repr.clone(),
                    source_indices.clone(),
                    variant_to_enum.clone(),
                    env.clone(),
                ));
            }
            __result
        });
        strs.join(&", ".to_string())
    }
}

pub fn emit_tco_param(
    param: Rc<Node>,
    generic_param_names: Rc<Vec<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    variant_to_enum: Rc<HashMap<String, String>>,
    env: Rc<TypeEnv>,
) -> String {
    {
        let authored = param_node_type_expr(param.clone());
        let ty = if ((authored.params.clone().len() as i64) > 0) {
            emit_rust_param_type(
                authored.clone(),
                generic_param_names,
                shared_types,
                corpus_repr,
                source_indices.clone(),
                variant_to_enum,
                env,
            )
        } else {
            render_rust_param_sig_type(
                param.clone(),
                generic_param_names,
                shared_types,
                corpus_repr,
                source_indices.clone(),
                variant_to_enum,
                env,
            )
        };
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    "mut ".to_string(),
                    emit_ident(
                        param_node_name_at(param.clone(), source_indices.clone()),
                        RenderTarget::Rust,
                    ),
                ),
                rust_items().param_type_sep.clone(),
            ),
            ty,
        )
    }
}

pub fn emit_func_params(
    params: Rc<Vec<Rc<Node>>>,
    uses: Rc<Vec<Rc<Node>>>,
    service_names: Rc<Vec<String>>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    read_only_params: Rc<std::collections::BTreeSet<String>>,
    variant_to_enum: Rc<HashMap<String, String>>,
    env: Rc<TypeEnv>,
) -> String {
    {
        let param_strs = Rc::new({
            let mut __result = Vec::new();
            for p in params.iter().cloned() {
                __result.push(emit_param(
                    p.clone(),
                    Rc::new(vec![]),
                    shared_types.clone(),
                    corpus_repr.clone(),
                    source_indices.clone(),
                    read_only_params.clone(),
                    variant_to_enum.clone(),
                    env.clone(),
                ));
            }
            __result
        });
        let resource_strs = Rc::new({
            let mut __result = Vec::new();
            for u in uses.iter().cloned() {
                __result.push(v1_rt::concat(
                    v1_rt::concat(
                        emit_ident(
                            resource_use_name_at(u.clone(), source_indices.clone()),
                            RenderTarget::Rust,
                        ),
                        ": &".to_string(),
                    ),
                    render_rust_type(
                        resource_use_resource(u.clone()),
                        shared_types.clone(),
                        corpus_repr.clone(),
                        source_indices.clone(),
                    ),
                ));
            }
            __result
        });
        let service_strs = Rc::new({
            let mut __result = Vec::new();
            for sn in service_names.iter().cloned() {
                __result.push(v1_rt::concat(
                    v1_rt::concat(service_var_name(sn.clone()), ": &".to_string()),
                    sanitize_service_name(sn.clone()),
                ));
            }
            __result
        });
        let all_params = v1_rt::concat(v1_rt::concat(param_strs, resource_strs), service_strs);
        all_params.join(&", ".to_string())
    }
}

pub fn emit_func_inferred(
    inferred: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    v1_rt::concat(
        v1_rt::concat(
            " -> Result<".to_string(),
            render_rust_type(inferred, shared_types, corpus_repr, source_indices),
        ),
        ", Box<dyn std::error::Error>>".to_string(),
    )
}

