pub fn effective_variant_parent(
    name: String,
    binding_kind: Option<Rc<VarBindingKind>>,
    resolved_type: Option<Rc<InferredNode>>,
    emit_info: Rc<EmitGraphInfo>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<String> {
    {
        let cached = match v1_rt::map_get(&emit_info.variant_to_enum.clone(), name.clone()) {
            Some(p) => {
                if (p.clone() != "".to_string()) {
                    Some(p.clone())
                } else {
                    None
                }
            }
            None => None,
        };
        match cached {
            Some(parent) => Some(parent.clone()),
            None => match resolved_type.as_deref().cloned() {
                Some(InferredNode::Resolved { node: rt, .. }) => {
                    let rt_name = authored_name_at(source_indices, rt.clone());
                    if (((rt.ident_span.clone() != None) && (rt_name.clone() != name.clone()))
                        && variant_belongs_to_enum(
                            emit_info.type_summaries.clone(),
                            name.clone(),
                            rt_name.clone(),
                        ))
                    {
                        Some(rt_name.clone())
                    } else {
                        variant_parent_from_binding_kind(binding_kind)
                    }
                }
                _ => variant_parent_from_binding_kind(binding_kind),
            },
        }
    }
}

pub fn variant_ref_self_wraps(
    name: String,
    enum_name: String,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
) -> bool {
    ((((name == "Empty".to_string()) && (enum_name.clone() == "FreeMonoid".to_string()))
        && corpus_repr_is_host(corpus_repr))
        || v1_rt::set_contains(&shared_types, enum_name.clone()))
}

pub fn move_licensed_at_site(emit_info: Rc<EmitGraphInfo>, name: String, use_span: i64) -> bool {
    if (use_span.clone() == 0) {
        false
    } else {
        match v1_rt::map_get(
            &emit_info.move_sites.clone(),
            move_site_key(name.clone(), use_span.clone()),
        ) {
            Some(v) => {
                (v.clone()
                    && !v1_rt::set_contains(&emit_info.read_only_params.clone(), name.clone()))
            }
            None => false,
        }
    }
}

pub fn emit_var_ref(
    name: String,
    binding_kind: Option<Rc<VarBindingKind>>,
    resolved_type: Option<Rc<InferredNode>>,
    use_span: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    emit_info: Rc<EmitGraphInfo>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    if ((name.clone() == "none".to_string()) || (name.clone() == "None".to_string())) {
        emit_keyword("null".to_string(), RenderTarget::Rust)
    } else {
        if ((name.clone() == "true".to_string()) || (name.clone() == "false".to_string())) {
            emit_keyword(name.clone(), RenderTarget::Rust)
        } else {
            {
                let site_move_kind_allowed = match binding_kind.clone().as_deref().cloned() {
                    Some(VarBindingKind::MatchBoundBinding) => false,
                    Some(VarBindingKind::FunctionValueBinding) => false,
                    Some(VarBindingKind::VariantValueBinding { parent_enum: _, .. }) => false,
                    _ => true,
                };
                let moves_by_value =
                    (v1_rt::set_contains(&emit_info.movable.clone(), name.clone())
                        || (site_move_kind_allowed
                            && move_licensed_at_site(emit_info.clone(), name.clone(), use_span)));
                let sharing = language_spec(RenderTarget::Rust).sharing.clone();
                let variant_parent = effective_variant_parent(
                    name.clone(),
                    binding_kind.clone(),
                    resolved_type.clone(),
                    emit_info.clone(),
                    source_indices,
                );
                let ref_str = match variant_parent {
                    Some(enum_name) => {
                        let body = if (((name.clone() == "Empty".to_string())
                            && (enum_name.clone() == "FreeMonoid".to_string()))
                            && corpus_repr_is_host(emit_info.corpus_repr.clone()))
                        {
                            "vec![]".to_string()
                        } else {
                            if (is_optional_variant_name(name.clone())
                                && (enum_name.clone() == "Optional".to_string()))
                            {
                                if (name.clone() == "Present".to_string()) {
                                    "Some".to_string()
                                } else {
                                    "None".to_string()
                                }
                            } else {
                                v1_rt::concat(
                                    v1_rt::concat(enum_name.clone(), "::".to_string()),
                                    name.clone(),
                                )
                            }
                        };
                        if variant_ref_self_wraps(
                            name.clone(),
                            enum_name.clone(),
                            shared_types,
                            emit_info.corpus_repr.clone(),
                        ) {
                            v1_rt::concat(
                                v1_rt::concat("Rc::new(".to_string(), body),
                                ")".to_string(),
                            )
                        } else {
                            body
                        }
                    }
                    None => match v1_rt::map_get(&registry, name.clone()) {
                        Some(info) => {
                            let is_data = (info.kind.clone() == ItemKind::DataItem);
                            if is_data {
                                v1_rt::concat(to_snake(name.clone()), "()".to_string())
                            } else {
                                {
                                    let is_function_value =
                                        match binding_kind.clone().as_deref().cloned() {
                                            Some(VarBindingKind::FunctionValueBinding) => true,
                                            _ => false,
                                        };
                                    let ident = emit_ident(name.clone(), RenderTarget::Rust);
                                    let ident_str = if is_function_value {
                                        ident
                                    } else {
                                        if moves_by_value {
                                            ident
                                        } else {
                                            match resolved_type.clone() {
                                                Some(_) => apply_type_template1(
                                                    sharing.clone_value.clone(),
                                                    ident,
                                                ),
                                                _ => ident,
                                            }
                                        }
                                    };
                                    ident_str
                                }
                            }
                        }
                        None => {
                            let ident = emit_ident(name.clone(), RenderTarget::Rust);
                            let ident_str = if moves_by_value {
                                ident
                            } else {
                                match resolved_type.clone() {
                                    Some(_) => {
                                        apply_type_template1(sharing.clone_value.clone(), ident)
                                    }
                                    _ => ident,
                                }
                            };
                            ident_str
                        }
                    },
                };
                ref_str
            }
        }
    }
}

pub fn emit_typed_expr_base(
    texpr: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let si = (*scope.type_env).clone().source_indices.clone();
        match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprVar {
                binding_kind: binding_kind,
                ..
            } => {
                let n = expr_var_name_at(texpr.clone(), si.clone());
                if ((n.clone() == "none".to_string()) || (n.clone() == "None".to_string())) {
                    emit_keyword("null".to_string(), RenderTarget::Rust)
                } else {
                    if ((n.clone() == "true".to_string()) || (n.clone() == "false".to_string())) {
                        emit_keyword(n.clone(), RenderTarget::Rust)
                    } else {
                        {
                            let variant_parent = effective_variant_parent(
                                n.clone(),
                                binding_kind.clone(),
                                texpr.inferred.clone(),
                                emit_info.clone(),
                                si.clone(),
                            );
                            match variant_parent {
                                Some(enum_name) => {
                                    if (((n.clone() == "Empty".to_string())
                                        && (enum_name.clone() == "FreeMonoid".to_string()))
                                        && corpus_repr_is_host(emit_info.corpus_repr.clone()))
                                    {
                                        "Rc::new(vec![])".to_string()
                                    } else {
                                        {
                                            let qualified = if (is_optional_variant_name(n.clone())
                                                && (enum_name.clone() == "Optional".to_string()))
                                            {
                                                if (n.clone() == "Present".to_string()) {
                                                    "Some".to_string()
                                                } else {
                                                    "None".to_string()
                                                }
                                            } else {
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        enum_name.clone(),
                                                        "::".to_string(),
                                                    ),
                                                    n.clone(),
                                                )
                                            };
                                            if v1_rt::set_contains(&shared_types, enum_name.clone())
                                            {
                                                v1_rt::concat(
                                                    v1_rt::concat(
                                                        "Rc::new(".to_string(),
                                                        qualified,
                                                    ),
                                                    ")".to_string(),
                                                )
                                            } else {
                                                qualified
                                            }
                                        }
                                    }
                                }
                                None => match v1_rt::map_get(&registry, n.clone()) {
                                    Some(info) => {
                                        let is_data = (info.kind.clone() == ItemKind::DataItem);
                                        if is_data {
                                            v1_rt::concat(to_snake(n.clone()), "()".to_string())
                                        } else {
                                            emit_ident(n.clone(), RenderTarget::Rust)
                                        }
                                    }
                                    None => emit_ident(n.clone(), RenderTarget::Rust),
                                },
                            }
                        }
                    }
                }
            }
            _ => emit_typed_expr(
                texpr.clone(),
                registry,
                scope.clone(),
                depth,
                shared_types,
                emit_info.clone(),
                1024,
            ),
        }
    }
}

pub fn field_access_field_is_boxed(
    base: Rc<Node>,
    field: String,
    scope: Rc<InferScope>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> bool {
    {
        let base_struct = expand_type_for_field_access(
            resolved_type(base),
            scope.type_env.clone(),
            scope.module_name.clone(),
        );
        match find_child_named(
            base_struct,
            field,
            (*scope.type_env).clone().source_indices.clone(),
        ) {
            Some(field_child) => {
                let field_ty = resolved_type(field_child.clone());
                let field_ty_name = authored_name_at(
                    (*scope.type_env).clone().source_indices.clone(),
                    field_ty.clone(),
                );
                let grounds_to_host_scalar = (rust_seed_host_numeric_alias(
                    field_ty_name.clone(),
                    emit_info.corpus_repr.clone(),
                ) != None);
                if grounds_to_host_scalar {
                    false
                } else {
                    {
                        let faithful_nat_field = ((emit_info.corpus_repr.clone()
                            == RustCorpusRepr::FaithfulFreeMonoid)
                            && ((field_ty_name.clone() == "Nat".to_string())
                                || (v1_rt::substring(&field_ty_name, 0, 4) == "Nat<".to_string())));
                        ((faithful_nat_field
                            || needs_box_wrapping(
                                field_ty.clone(),
                                emit_info.recursive_type_set.clone(),
                                shared_types,
                                (*scope.type_env).clone().source_indices.clone(),
                            ))
                            || is_recursive_type_by_name(
                                scope.type_env.clone(),
                                field_ty_name.clone(),
                            ))
                    }
                }
            }
            None => false,
        }
    }
}

pub fn emit_typed_field_access(
    base: Rc<Node>,
    field: String,
    summary: Option<Rc<FieldSummary>>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let base_str = emit_typed_expr_base(
            base.clone(),
            registry.clone(),
            scope.clone(),
            depth.clone(),
            shared_types.clone(),
            emit_info.clone(),
        );
        let base_is_anon_record = match base.inferred.clone().as_deref().cloned() {
            Some(InferredNode::Resolved { node: bt, .. }) => {
                let is_product = is_product_type(bt.clone());
                if (is_product && (bt.ident_span.clone() == None)) {
                    true
                } else {
                    false
                }
            }
            _ => false,
        };
        if base_is_anon_record {
            {
                let bt = resolved_type(base.clone());
                if ((bt.children.clone().len() as i64) == 1) {
                    emit_typed_expr(
                        base.clone(),
                        registry.clone(),
                        scope.clone(),
                        depth.clone(),
                        shared_types.clone(),
                        emit_info.clone(),
                        1024,
                    )
                } else {
                    {
                        let matches = Rc::new({
                            let mut __result = Vec::new();
                            for pair in Rc::new(
                                bt.children
                                    .clone()
                                    .iter()
                                    .cloned()
                                    .enumerate()
                                    .map(|(i, v)| (i as i64, v))
                                    .collect::<Vec<_>>(),
                            )
                            .iter()
                            .cloned()
                            {
                                if (authored_name_at(
                                    (*scope.type_env).clone().source_indices.clone(),
                                    pair.1.clone(),
                                ) == field.clone())
                                {
                                    __result.push(pair);
                                }
                            }
                            __result
                        });
                        match matches.first().cloned() {
                            Some(m) => {
                                let sharing = language_spec(RenderTarget::Rust).sharing.clone();
                                apply_type_template1(
                                    sharing.clone_value.clone(),
                                    v1_rt::concat(
                                        v1_rt::concat(base_str, ".".to_string()),
                                        (m.0.clone()).to_string(),
                                    ),
                                )
                            }
                            None => v1_rt::concat(
                                v1_rt::concat(
                                    "compile_error!(\"anonymous record field not found: "
                                        .to_string(),
                                    field.clone(),
                                ),
                                "\")".to_string(),
                            ),
                        }
                    }
                }
            }
        } else {
            {
                let sharing = language_spec(RenderTarget::Rust).sharing.clone();
                match summary {
                    Some(field_summary) => match field_summary.access_style.clone() {
                        FieldAccessStyle::TupleFirst => apply_type_template1(
                            sharing.clone_value.clone(),
                            v1_rt::concat(base_str, ".0".to_string()),
                        ),
                        FieldAccessStyle::TupleSecond => apply_type_template1(
                            sharing.clone_value.clone(),
                            v1_rt::concat(base_str, ".1".to_string()),
                        ),
                        FieldAccessStyle::OptionalUnwrap => v1_rt::concat(
                            apply_type_template1(sharing.clone_value.clone(), base_str),
                            ".unwrap()".to_string(),
                        ),
                        FieldAccessStyle::EnumAccessor => v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(base_str, ".".to_string()),
                                emit_ident(field.clone(), RenderTarget::Rust),
                            ),
                            "()".to_string(),
                        ),
                        FieldAccessStyle::StoredField => {
                            let base_is_owned = match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let base_name = expr_var_name_at(
                                        base.clone(),
                                        (*scope.type_env).clone().source_indices.clone(),
                                    );
                                    v1_rt::set_contains(
                                        &emit_info.owned_bindings.clone(),
                                        base_name,
                                    )
                                }
                                _ => false,
                            };
                            let field_is_boxed = field_access_field_is_boxed(
                                base.clone(),
                                field.clone(),
                                scope.clone(),
                                shared_types.clone(),
                                emit_info.clone(),
                            );
                            if field_is_boxed {
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat("(*".to_string(), base_str),
                                            ".".to_string(),
                                        ),
                                        emit_ident(field.clone(), RenderTarget::Rust),
                                    ),
                                    ").clone()".to_string(),
                                )
                            } else {
                                if base_is_owned {
                                    v1_rt::concat(
                                        v1_rt::concat(base_str, ".".to_string()),
                                        emit_ident(field.clone(), RenderTarget::Rust),
                                    )
                                } else {
                                    apply_type_template1(
                                        sharing.clone_value.clone(),
                                        v1_rt::concat(
                                            v1_rt::concat(base_str, ".".to_string()),
                                            emit_ident(field.clone(), RenderTarget::Rust),
                                        ),
                                    )
                                }
                            }
                        }
                    },
                    None => v1_rt::concat(
                        v1_rt::concat(
                            "compile_error!(\"field access missing reconcile summary for '"
                                .to_string(),
                            field.clone(),
                        ),
                        "'\")".to_string(),
                    ),
                }
            }
        }
    }
}

pub fn type_needs_rc(
    type_node: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    type_needs_rc_seen(
        type_node,
        v1_rt::rc_empty_map::<String, bool>(),
        source_indices,
    )
}

pub fn type_needs_rc_seen(
    mut type_node: Rc<Node>,
    mut seen: Rc<HashMap<String, bool>>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        let normed = normalize_access_type_node(type_node);
        let is_product = is_product_type(normed.clone());
        let is_coproduct = is_coproduct_type(normed.clone());
        if is_product {
            break true;
        } else {
            if is_coproduct {
                break {
                    let mut __found = false;
                    for child in normed.children.clone().iter().cloned() {
                        if ((child.children.clone().len() as i64) > 0) {
                            __found = true;
                            break;
                        }
                    }
                    __found
                };
            } else {
                let canonical = authored_name_at(source_indices.clone(), normed.clone());
                if (normed.inferred.clone() != None) {
                    let next_seen = if (canonical.clone() == "".to_string()) {
                        seen.clone()
                    } else {
                        v1_rt::rc_map_insert(seen.clone(), canonical.clone(), true)
                    };
                    {
                        let __tco_0 = resolved_type(normed.clone());
                        let __tco_1 = next_seen;
                        type_node = __tco_0;
                        seen = __tco_1;
                        continue;
                    }
                } else {
                    if ((canonical.clone() != "".to_string())
                        && emit_map_has(seen.clone(), canonical.clone()))
                    {
                        break false;
                    } else {
                        let next_seen = if (canonical.clone() == "".to_string()) {
                            seen.clone()
                        } else {
                            v1_rt::rc_map_insert(seen.clone(), canonical.clone(), true)
                        };
                        let has_structure = (normed.connective.clone() != Connective::NoConnective);
                        if (!has_structure && ((normed.children.clone().len() as i64) == 0)) {
                            break false;
                        } else {
                            {
                                let __tco_0 = normed.clone();
                                let __tco_1 = next_seen;
                                type_node = __tco_0;
                                seen = __tco_1;
                                continue;
                            }
                        }
                    }
                }
            }
        }
    }
}

