pub fn rust_empty_map_value_type_str(
    map_type: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match map_type.children.clone().get(1 as usize).cloned() {
        Some(value_child) => {
            let rendered = render_rust_type(
                child_type_node(value_child.clone()),
                shared_types,
                corpus_repr,
                source_indices,
            );
            if (rendered.clone() == "".to_string()) {
                "".to_string()
            } else {
                rendered.clone()
            }
        }
        None => "".to_string(),
    }
}

pub fn rust_empty_map_kv_type_str(
    map_type: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    corpus_repr: RustCorpusRepr,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let key_str = match map_type.children.clone().first().cloned() {
            Some(key_child) => render_rust_type(
                child_type_node(key_child.clone()),
                shared_types.clone(),
                corpus_repr.clone(),
                source_indices.clone(),
            ),
            None => "".to_string(),
        };
        let val_str = rust_empty_map_value_type_str(
            map_type.clone(),
            shared_types.clone(),
            corpus_repr.clone(),
            source_indices.clone(),
        );
        if ((key_str.clone() != "".to_string()) && (val_str.clone() != "".to_string())) {
            v1_rt::concat(
                v1_rt::concat(key_str.clone(), ", ".to_string()),
                val_str.clone(),
            )
        } else {
            "".to_string()
        }
    }
}

pub fn type_node_child_is_type_variable(c: Rc<Node>) -> bool {
    {
        let ch = child_type_node(c);
        if (ch.inferred.clone() != None) {
            is_type_variable(ch.inferred.clone().clone().unwrap())
        } else {
            false
        }
    }
}

pub fn rust_btree_set_element_ord_eligible(
    elem_node: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let elem_name = authored_name_at(source_indices.clone(), elem_node.clone());
        (((((((elem_name.clone() == "String".to_string())
            || (elem_name.clone() == "Int".to_string()))
            || (elem_name.clone() == "Bool".to_string()))
            || (elem_name.clone() == "Unit".to_string()))
            || (elem_name.clone() == "Secret".to_string()))
            || (elem_name.clone() == "Bytes".to_string()))
            || rust_nominal_ord_type_eligible(elem_node.clone(), source_indices.clone()))
    }
}

pub fn rust_empty_set_element_type_str(
    set_type: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match set_type.children.clone().first().cloned() {
        Some(elem_child) => {
            let elem_node = child_type_node(elem_child.clone());
            let elem_is_type_var = if (elem_node.inferred.clone() != None) {
                is_type_variable(elem_node.inferred.clone().clone().unwrap())
            } else {
                false
            };
            let elem_is_error = if (elem_node.inferred.clone() != None) {
                is_compiler_error(elem_node.inferred.clone().clone().unwrap())
            } else {
                false
            };
            if (elem_is_type_var || elem_is_error) {
                "".to_string()
            } else {
                if !rust_btree_set_element_ord_eligible(elem_node.clone(), source_indices.clone()) {
                    "".to_string()
                } else {
                    render_node_type(
                        elem_node.clone(),
                        RenderTarget::Rust,
                        shared_types,
                        source_indices.clone(),
                    )
                }
            }
        }
        None => "".to_string(),
    }
}

pub fn emit_rust_empty_set_expr(
    set_type: Rc<Node>,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match set_type.children.clone().first().cloned() {
        Some(elem_child) => {
            let elem_node = child_type_node(elem_child.clone());
            let elem_is_type_var = if (elem_node.inferred.clone() != None) {
                is_type_variable(elem_node.inferred.clone().clone().unwrap())
            } else {
                false
            };
            if elem_is_type_var {
                "v1_rt::rc_empty_set::<_>()".to_string()
            } else {
                if !rust_btree_set_element_ord_eligible(elem_node.clone(), source_indices.clone()) {
                    {
                        let elem_name = authored_name_at(source_indices.clone(), elem_node.clone());
                        emit_rust_compile_error_expr(v1_rt::concat(
                            v1_rt::concat("empty_set element type ".to_string(), elem_name),
                            " is not Ord-eligible for BTreeSet".to_string(),
                        ))
                    }
                } else {
                    {
                        let elem_str = rust_empty_set_element_type_str(
                            set_type.clone(),
                            shared_types,
                            source_indices.clone(),
                        );
                        if (elem_str.clone() != "".to_string()) {
                            v1_rt::concat(
                                v1_rt::concat(
                                    "v1_rt::rc_empty_set::<".to_string(),
                                    elem_str.clone(),
                                ),
                                ">()".to_string(),
                            )
                        } else {
                            "v1_rt::rc_empty_set::<_>()".to_string()
                        }
                    }
                }
            }
        }
        None => "v1_rt::rc_empty_set::<_>()".to_string(),
    }
}

pub fn rust_runtime_bridge_wraps_collection_result_in_rc(function_name: String) -> bool {
    (v1_rt::map_contains_key(&rt_wraps_result(), function_name.clone())
        || v1_rt::map_contains_key(&rust_method_wraps_result(), function_name.clone()))
}

pub fn rust_runtime_bridge_collection_result_needs_rc_elements(
    function_name: String,
    result_type: Option<Rc<InferredNode>>,
) -> bool {
    false
}

pub fn rust_wrap_runtime_collection_result(
    call_str: String,
    function_name: String,
    result_type: Option<Rc<InferredNode>>,
) -> String {
    if rust_runtime_bridge_wraps_collection_result_in_rc(function_name.clone()) {
        if rust_runtime_bridge_collection_result_needs_rc_elements(
            function_name.clone(),
            result_type,
        ) {
            v1_rt::concat(
                v1_rt::concat("Rc::new((".to_string(), call_str),
                ").into_iter().map(Rc::new).collect::<Vec<_>>())".to_string(),
            )
        } else {
            v1_rt::concat(
                v1_rt::concat("Rc::new(".to_string(), call_str),
                ")".to_string(),
            )
        }
    } else {
        call_str
    }
}

