pub fn emit_rust_expr_field_access(
    expr: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    {
        let si = (*scope.type_env).clone().source_indices.clone();
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprFieldAccess {
                summary: summary, ..
            } => {
                let f = field_access_field_at(expr.clone(), si);
                let b = field_access_base(expr.clone());
                if is_typed_service_call_receiver(
                    expr.clone(),
                    (*scope.type_env).clone().source_indices.clone(),
                ) {
                    match extract_typed_service_name(
                        expr.clone(),
                        (*scope.type_env).clone().source_indices.clone(),
                    ) {
                        Some(svc_name) => service_var_name(svc_name.clone()),
                        None => emit_typed_field_access(
                            b,
                            f,
                            summary.clone(),
                            registry,
                            scope.clone(),
                            depth,
                            shared_types,
                            emit_info,
                        ),
                    }
                } else {
                    emit_typed_field_access(
                        b,
                        f,
                        summary.clone(),
                        registry,
                        scope.clone(),
                        depth,
                        shared_types,
                        emit_info,
                    )
                }
            }
            _ => emit_error_expr(
                "emit_rust_expr_field_access expected ExprFieldAccess".to_string(),
                RenderTarget::Rust,
            ),
        }
    }
}

