pub fn emit_rust_expr_record_lit(
    expr: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprRecordLit {
            parent_enum: parent_enum,
            ..
        } => {
            let tn = record_lit_type_name_at(
                expr.clone(),
                (*scope.type_env).clone().source_indices.clone(),
            );
            let fs = expr.children.clone();
            let si = (*scope.type_env).clone().source_indices.clone();
            let resolved_rt = resolved_type(expr.clone());
            let expanded_rt = expand_type_for_field_access(
                resolved_rt,
                scope.type_env.clone(),
                scope.module_name.clone(),
            );
            let variant_name = match tn.clone() {
                Some(n) => n.clone(),
                None => "".to_string(),
            };
            let peeled_type_name = if (((parent_enum.clone() == None)
                && (expanded_rt.connective.clone() == Connective::Conj))
                && (expanded_rt.ident_span.clone() != None))
            {
                {
                    let concrete = authored_name_at(si.clone(), expanded_rt.clone());
                    if ((concrete.clone() != "".to_string())
                        && (concrete.clone() != variant_name.clone()))
                    {
                        Some(concrete.clone())
                    } else {
                        tn.clone()
                    }
                }
            } else {
                tn.clone()
            };
            let raw = emit_typed_record_lit(
                peeled_type_name,
                fs,
                parent_enum.clone(),
                expanded_rt.clone(),
                registry,
                scope.clone(),
                depth,
                shared_types.clone(),
                emit_info.clone(),
            );
            let rc_name = match parent_enum.clone() {
                Some(en) => en.clone(),
                None => match contextual_variant_parent(
                    variant_name.clone(),
                    parent_enum.clone(),
                    expanded_rt.clone(),
                    emit_info.clone(),
                    si.clone(),
                ) {
                    Some(p) => p.clone(),
                    None => {
                        let expanded_name = authored_name_at(si.clone(), expanded_rt.clone());
                        if ((((expanded_rt.ident_span.clone() != None)
                            && (expanded_name.clone() != "".to_string()))
                            && (expanded_name.clone() != variant_name.clone()))
                            && v1_rt::set_contains(&shared_types, expanded_name.clone()))
                        {
                            expanded_name.clone()
                        } else {
                            variant_name.clone()
                        }
                    }
                },
            };
            if ((rc_name.clone() != "".to_string())
                && v1_rt::set_contains(&shared_types, rc_name.clone()))
            {
                v1_rt::concat(v1_rt::concat("Rc::new(".to_string(), raw), ")".to_string())
            } else {
                raw
            }
        }
        _ => emit_error_expr(
            "emit_rust_expr_record_lit expected ExprRecordLit".to_string(),
            RenderTarget::Rust,
        ),
    }
}

pub fn emit_rust_expr_string_interp(
    expr: Rc<Node>,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    shared_types: Rc<std::collections::BTreeSet<String>>,
    emit_info: Rc<EmitGraphInfo>,
) -> String {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprStringInterp => {
            let ps = Rc::new({
                let mut __result = Vec::new();
                for child in expr.children.clone().iter().cloned() {
                    __result.push(match (*child.expr_data.clone()).clone() {
                        ExprData::ExprLiteral { ref value, .. } => {
                            let LiteralValue::LitStr { value: text, .. } = value.as_ref() else {
                                unreachable!()
                            };
                            Rc::new(StringPart::Text {
                                value: text.clone(),
                            })
                        }
                        _ => Rc::new(StringPart::Interpolation {
                            expr: arg_value(child.clone()),
                        }),
                    });
                }
                __result
            });
            emit_typed_string_interp(ps, registry, scope, depth, shared_types, emit_info)
        }
        _ => emit_error_expr(
            "emit_rust_expr_string_interp expected ExprStringInterp".to_string(),
            RenderTarget::Rust,
        ),
    }
}

